let _prePackScanLastCode_ = '';
let _prePackScanLastAt_ = 0;
async function _prePackScanTick_() {
  if (!window._prePackScanStream_ || !window._prePackScanDetector_) return;
  const video = document.getElementById('prePackScanVideo');
  const feedback = document.getElementById('prePackScanFeedback');
  if (!video || !feedback) return;
  try {
    const codes = await window._prePackScanDetector_.detect(video);
    if (codes && codes.length) {
      const raw = String(codes[0].rawValue || '').trim();
      const now = Date.now();
      if (raw && (raw !== _prePackScanLastCode_ || (now - _prePackScanLastAt_) > 1500)) {
        _prePackScanLastCode_ = raw;
        _prePackScanLastAt_ = now;
        feedback.textContent = '✓ ' + raw;
        const input = document.getElementById('prePackScanInput');
        if (input) {
          input.value = raw;
          // Simulate Enter key to trigger handlePrePackScanKey
          const event = new KeyboardEvent('keydown', { key: 'Enter', bubbles: true });
          input.dispatchEvent(event);
        }
        if (typeof FB !== 'undefined' && FB.success) FB.success();
      }
    }
  } catch (e) {}
  setTimeout(_prePackScanTick_, 300);
}

function closePrePackCameraScan_() {
  if (window._prePackScanStream_) {
    try { window._prePackScanStream_.getTracks().forEach(t => t.stop()); } catch(e) {}
    window._prePackScanStream_ = null;
  }
  window._prePackScanDetector_ = null;
  _prePackScanLastCode_ = '';
  _prePackScanLastAt_ = 0;
  const ov = document.getElementById('prePackScanOverlay');
  if (ov) ov.remove();
}

// v10.306 — Zac 12:48 EDT: 'details have no customer or address.'
// Synchronous Shopify pull on-demand. Slow (~5s) but only fires when
// user explicitly taps the button — most-of-the-time the background
// sweep heals these silently. Reopens Pack detail to repaint.
async function refreshShopifyCustomerForOrder_(orderNumber) {
  return _guardedAction_({
    key: 'shopifyRefresh:' + orderNumber,
    btnSelector: 'button[onclick="refreshShopifyCustomerForOrder_(\'' + orderNumber + '\')"]',
    busyText: '⏳ Pulling…',
    action: async () => {
      showToast('⏳ Pulling customer details from Shopify…');
      try {
        const res = await groundApi('runShopifyCustomerBackfillSweep', { limit: 1, only_order: String(orderNumber) });
        if (!res || !res.ok) {
          showToast('⚠ Refresh failed: ' + ((res && res.error) || 'unknown'));
          return;
        }
        const boot = await groundApi('ensurePackQueueRowExists', { orderNumber: String(orderNumber) });
        if (boot && boot.ok && boot.row) {
          const cache = (typeof _packQueueCache !== 'undefined' && _packQueueCache) || [];
          const idx = cache.findIndex(r => String(r.order_number) === String(orderNumber));
          if (idx >= 0) cache[idx] = boot.row; else cache.unshift(boot.row);
          if (typeof openPackDetail === 'function') openPackDetail(orderNumber);
        }
        showToast('✓ Customer pulled from Shopify');
      } catch (e) {
        showToast('Refresh error: ' + e.message);
      }
    },
  });
}

// v10.314 — Zac: "aren't you supposed to be mapping to instructions
// by sku on your own at this point, not using the JS2 pick list link?"
// Single unified entry point for every Print Instructions button
// (Instructions-row chip, INST-* SKU-row chip, big bottom button).
//
// Flow:
//   1. Find all INST-* SKUs on the order's parsed pick list
//   2. Server-resolve each SKU via the InstructionsMap tab
//   3. 1 hit: stamp + print that PDF
//   4. 2+ hits: open picker modal (Print All combined / Print Selected)
//   5. 0 hits: show clear "no map entry — open Instructions Map" banner
//   6. NEVER fall back to the pick list PDF
// v10.543 — print just the pick-list PDF (no cover prepend, no
// instructions append). Used by the "Inst + Pick List" combined
// option and by the bulk picker's "Also print pick list" checkbox.
// Pick list goes to PrintNode as a separate job so the operator
// can grab it from the office tray as a quick reference sheet.
async function printPickListOnly_(orderNumber) {
  const orderStr = String(orderNumber || '').trim();
  if (!orderStr) return { ok: false, error: 'orderNumber required' };
  // v10.550 — delegate URL resolution + Drive fetch + PrintNode submit
  // to the server. The DIAG on 32191 showed the gcal event HAD the
  // Drive URL but the PackingQueue row's pick_list_pdf_url column was
  // empty (sku_source='shopify+native' — row predates the pick-list
  // email). The server now falls back to gcal when the column is
  // blank and auto-backfills the column. Client no longer needs to
  // know the URL — just the order#.
  try {
    return await groundApi('printPickListPdfForOrder', { orderNumber: orderStr });
  } catch (e) {
    return { ok: false, error: 'pick list print error: ' + (e.message || e) };
  }
}

// v10.548 — toast-wrapped pick-list-only entry point. The raw
// printPickListOnly_ returns a result object silently (used by the
// bulk runner). This wrapper gives single-button taps a user-visible
// result so Zac sees what happened.
// v10.551 — Bedrock-native pick list print + gcal validation diff.
// Per Zac 2026-06-12: "make your own pick lists ... and double-check
// contents against pick list pdf in gcal if one exists." Side-by-side
// rollout — native generator + validation visible on the detail
// screen; once trust is established the gcal-linked PDFs can retire.
async function printNativePickList_(orderNumber) {
  const ord = String(orderNumber || '').trim();
  if (!ord) return;
  // v10.906 — Zac 2026-06-30: "native pick list thing should show it
  // first then one can select to print from bedrock to the default paper
  // printer or not." Redirect to the Inspect Order modal (which already
  // has the full BOM preview + a 🖨 Print button) so the packer sees
  // exactly what would print before it fires. Cancel is just Esc.
  if (typeof openInspectOrderModal === 'function') {
    openInspectOrderModal(ord);
    return;
  }
  // Fallback if the Inspect Order surface isn't loaded (shouldn't happen
  // on a fresh page load): direct print with the persistent overlay from
  // v10.889.
  _printNativePickListDirect_(ord);
}

// v10.906 — the previous "fire straight to print" path is preserved
// for the (rare) fallback + can be re-wired to a "Skip preview, print
// now" option if we ever add one back.
async function _printNativePickListDirect_(ord) {
  const prev = document.getElementById('printNativePickListOv');
  if (prev) prev.remove();
  const ov = document.createElement('div');
  ov.id = 'printNativePickListOv';
  ov.style.cssText = 'position:fixed;inset:0;z-index:10040;background:rgba(0,0,0,.78);display:flex;align-items:center;justify-content:center;padding:24px';
  ov.innerHTML = `
    <div style="background:#0E1520;color:#fff;-webkit-text-fill-color:#fff;border:1.5px solid rgba(0,135,254,.45);border-radius:14px;max-width:520px;width:100%;padding:22px;font-family:Helvetica,Arial,sans-serif">
      <div style="display:flex;align-items:center;gap:14px;margin-bottom:14px">
        <div id="pnplSpinner" style="width:28px;height:28px;border:3px solid rgba(66,165,245,.30);border-top-color:#42a5f5;border-radius:50%;animation:mbdSpin 1s linear infinite;flex-shrink:0"></div>
        <div style="flex:1">
          <div id="pnplTitle" style="font-size:16px;font-weight:800;color:#fff;-webkit-text-fill-color:#fff">Building pick list for #${ord}…</div>
          <div id="pnplSub" style="font-size:12px;color:rgba(255,255,255,.65);-webkit-text-fill-color:rgba(255,255,255,.65);margin-top:3px">Server is rendering the PDF + sending to PrintNode (up to ~20s)</div>
        </div>
      </div>
      <div id="pnplFooter" style="display:none;text-align:right">
        <button onclick="document.getElementById('printNativePickListOv').remove()" style="padding:9px 18px;background:#1565c0;color:#fff;-webkit-text-fill-color:#fff;border:none;border-radius:6px;cursor:pointer;font-weight:700">OK</button>
      </div>
    </div>`;
  document.body.appendChild(ov);
  const setOverlay = (icon, color, title, sub, showOk) => {
    const sp = document.getElementById('pnplSpinner');
    const t = document.getElementById('pnplTitle');
    const s = document.getElementById('pnplSub');
    const f = document.getElementById('pnplFooter');
    if (!sp || !t || !s || !f) return;
    sp.style.animation = 'none';
    sp.style.border = 'none';
    sp.style.fontSize = '26px';
    sp.style.color = color;
    sp.style.webkitTextFillColor = color;
    sp.innerHTML = icon;
    t.innerHTML = title;
    s.innerHTML = sub;
    if (showOk) f.style.display = 'block';
  };
  try {
    const res = await groundApi('printNativePickListForOrder', { orderNumber: ord });
    if (res && res.ok) {
      setOverlay('✓', '#0a7a3f', '✓ Pick list printed for #' + ord, 'Sent to PrintNode (printer ' + (res.printer_id || '?') + ', job ' + (res.job_id || '?') + ')', true);
      // Auto-dismiss after 6s on success
      setTimeout(() => { const x = document.getElementById('printNativePickListOv'); if (x) x.remove(); }, 6000);
    } else {
      const err = (res && res.error) || 'unknown error';
      setOverlay('⚠', '#FF6B00', '⚠ Print FAILED for #' + ord, String(err).replace(/</g,'&lt;'), true);
    }
  } catch (e) {
    setOverlay('⚠', '#c33', '⚠ Network error', String(e.message || e), true);
  }
}

async function openNativePickListValidationModal_(orderNumber) {
  const ord = String(orderNumber || '').trim();
  if (!ord) return;
  const prior = document.getElementById('nativePickListValidationOv');
  if (prior) prior.remove();
  const ov = document.createElement('div');
  ov.id = 'nativePickListValidationOv';
  ov.className = 'keep-dark-text';
  ov.style.cssText = 'position:fixed;inset:0;z-index:10031;background:rgba(0,0,0,.78);display:flex;align-items:center;justify-content:center;padding:20px';
  ov.innerHTML = '<div style="background:#0E1520;color:#fff;-webkit-text-fill-color:#fff;border:1.5px solid rgba(0,135,254,.45);border-radius:14px;max-width:780px;width:100%;max-height:88vh;display:flex;flex-direction:column;overflow:hidden">'
    + '<div style="padding:16px 20px;border-bottom:1px solid rgba(255,255,255,.10);display:flex;align-items:center;gap:10px">'
    + '<div style="flex:1;font-family:\'Barlow Condensed\',Arial,sans-serif;font-size:18px;font-weight:900;letter-spacing:1px">Pick list validation · #' + esc(ord) + '</div>'
    + '<button onclick="document.getElementById(\'nativePickListValidationOv\').remove()" style="background:transparent;color:#fff;-webkit-text-fill-color:#fff;border:none;font-size:22px;cursor:pointer">✕</button>'
    + '</div>'
    + '<div id="nativePickListValidationBody" style="flex:1;overflow-y:auto;padding:18px 20px">'
    + '<div style="display:flex;align-items:center;gap:12px;color:#42a5f5"><div style="width:24px;height:24px;border:3px solid rgba(66,165,245,.30);border-top-color:#42a5f5;border-radius:50%;animation:mbdSpin 1s linear infinite"></div><div>Comparing Bedrock native vs gcal pick list… (OCR may take 5–15s)</div></div>'
    + '</div>'
    + '<div style="padding:12px 20px;border-top:1px solid rgba(255,255,255,.10);display:flex;gap:10px;justify-content:flex-end">'
    + '<button onclick="printNativePickList_(\'' + esc(ord) + '\')" style="padding:10px 16px;background:#1565c0;color:#fff;-webkit-text-fill-color:#fff;border:none;border-radius:8px;font-size:13px;font-weight:800;cursor:pointer">🖨 Print Native Pick List</button>'
    + '</div></div>';
  document.body.appendChild(ov);
  let res;
  try {
    res = await groundApi('compareNativePickListWithGcal', { orderNumber: ord });
  } catch (e) {
    res = { ok: false, error: e.message || e };
  }
  const body = document.getElementById('nativePickListValidationBody');
  if (!body) return;
  if (!res || !res.ok) {
    body.innerHTML = '<div style="padding:20px;text-align:center;color:#ff5252">⚠ Validation failed: ' + esc((res && res.error) || 'unknown') + '</div>';
    return;
  }
  body.innerHTML = _renderNativePickListDiff_(res, ord);
}

function _renderNativePickListDiff_(res, ord) {
  const s = res.summary || {};
  let h = '';
  h += '<div style="display:flex;gap:10px;margin-bottom:14px;flex-wrap:wrap">';
  h += _diffChip_('✓ matched', s.matched || 0, '#00C853');
  h += _diffChip_('⚠ qty diff', s.qty_diffs || 0, '#FFB300');
  h += _diffChip_('+ Bedrock only', s.only_native || 0, '#42a5f5');
  h += _diffChip_('+ gcal only', s.only_gcal || 0, '#ce93d8');
  h += '</div>';
  if (s.gcal_available === false || res.gcal_error) {
    // v10.554 — targeted runbook when the error is specifically
    // "Drive is not defined" (= Advanced Drive Service not added to
    // the script project). Zac flagged that even after enabling the
    // Drive API in the Cloud Console, the OCR path still fails — the
    // Cloud Console enablement is necessary BUT NOT sufficient; the
    // Apps Script project ALSO needs the service added under
    // Services so the `Drive` global gets imported.
    const errStr = String(res.gcal_error || '');
    const isDriveNotDefined = /Drive is not defined/i.test(errStr) || /Advanced Drive Service may not be enabled/i.test(errStr);
    h += '<div style="padding:12px 14px;background:rgba(255,179,0,.10);border:1px solid rgba(255,179,0,.55);border-radius:8px;margin-bottom:14px;font-size:13px;line-height:1.5">'
      + '<div style="font-weight:800;color:#FFB300;-webkit-text-fill-color:#FFB300;margin-bottom:4px">⚠ Couldn\'t compare against gcal pick list — showing Bedrock expansion only.</div>'
      + (errStr ? '<div style="color:#fff;-webkit-text-fill-color:#fff;font-family:\'JetBrains Mono\',monospace;font-size:11px;background:rgba(0,0,0,.30);padding:6px 8px;border-radius:4px;margin-top:6px">' + esc(errStr) + '</div>' : '')
      + (res.gcal_url ? '<div style="margin-top:6px"><a href="' + esc(res.gcal_url) + '" target="_blank" rel="noopener" style="color:#42a5f5;font-size:11px;word-break:break-all">' + esc(res.gcal_url) + '</a> (source: ' + esc(res.gcal_url_source || '?') + ')</div>' : '')
      + (isDriveNotDefined
          ? '<div style="margin-top:8px;padding:8px 10px;background:rgba(0,135,254,.10);border:1px solid rgba(0,135,254,.45);border-radius:6px;color:#42a5f5;-webkit-text-fill-color:#42a5f5;font-size:12px;line-height:1.6">'
            + '<div style="font-weight:800;margin-bottom:4px">Fix — Drive global needs to be added in the Apps Script project (not just enabled in GCP):</div>'
            + '<div style="font-family:\'JetBrains Mono\',monospace;font-size:11px;color:#fff;-webkit-text-fill-color:#fff">'
            + '1. Open <a href="https://script.google.com/d/1CV_W1X1ueXFboZuqjv5pgyPp8d-3nCk4HCzu_djQz--utPbrulwT7bvG/edit" target="_blank" style="color:#42a5f5">the editor</a><br>'
            + '2. Left sidebar → <strong>Services</strong> → click the <strong>+</strong> icon<br>'
            + '3. Scroll to <strong>Drive API</strong> (NOT "Drive" or "DriveActivity")<br>'
            + '4. Keep identifier as <strong>Drive</strong>, version <strong>v3</strong><br>'
            + '5. Click <strong>Add</strong>. Then retry validation.'
            + '</div>'
            + '</div>'
          : '<div style="margin-top:6px;color:rgba(255,255,255,.65);font-size:11px">Also possible: the PDF is image-only (OCR returns empty text), or the upstream PDF format changed enough that the SKU-line extractor regex misses everything.</div>')
      + '</div>';
  } else if (res.gcal_url) {
    h += '<div style="font-size:11px;color:rgba(255,255,255,.65);margin-bottom:14px">Comparing against: <a href="' + esc(res.gcal_url) + '" target="_blank" rel="noopener" style="color:#42a5f5">' + esc(res.gcal_url) + '</a> (source: ' + esc(res.gcal_url_source || '?') + ')</div>';
  }
  if ((res.both_have_qty_diff || []).length) {
    h += '<div style="font-family:\'Barlow Condensed\',Arial,sans-serif;font-size:14px;font-weight:900;color:#FFB300;text-transform:uppercase;letter-spacing:1.5px;margin-bottom:6px">⚠ Qty differences</div>';
    h += _diffTable_(res.both_have_qty_diff.map(d => ({ sku: d.sku, native: d.native_qty, gcal: d.gcal_qty })), ['SKU', 'Bedrock qty', 'gcal qty']);
  }
  if ((res.onlyInBedrock || []).length) {
    h += '<div style="font-family:\'Barlow Condensed\',Arial,sans-serif;font-size:14px;font-weight:900;color:#42a5f5;text-transform:uppercase;letter-spacing:1.5px;margin:14px 0 6px">Only in Bedrock (' + res.onlyInBedrock.length + ')</div>';
    h += _diffTable_(res.onlyInBedrock.map(d => ({ sku: d.sku, qty: d.qty })), ['SKU', 'Qty']);
  }
  if ((res.onlyInGcal || []).length) {
    h += '<div style="font-family:\'Barlow Condensed\',Arial,sans-serif;font-size:14px;font-weight:900;color:#ce93d8;text-transform:uppercase;letter-spacing:1.5px;margin:14px 0 6px">Only in gcal (' + res.onlyInGcal.length + ')</div>';
    h += _diffTable_(res.onlyInGcal.map(d => ({ sku: d.sku, qty: d.qty })), ['SKU', 'Qty']);
  }
  if ((res.matches || []).length) {
    h += '<details style="margin-top:14px"><summary style="font-family:\'Barlow Condensed\',Arial,sans-serif;font-size:14px;font-weight:900;color:#00C853;text-transform:uppercase;letter-spacing:1.5px;cursor:pointer">✓ Matched (' + res.matches.length + ')</summary>';
    h += '<div style="margin-top:6px">' + _diffTable_(res.matches.map(d => ({ sku: d.sku, qty: d.qty })), ['SKU', 'Qty']) + '</div>';
    h += '</details>';
  }
  return h;
}

function _diffChip_(label, count, color) {
  return '<div style="padding:8px 14px;background:rgba(255,255,255,.04);border:1px solid ' + color + '55;border-radius:999px;font-size:13px;font-weight:800;color:' + color + ';-webkit-text-fill-color:' + color + ';display:inline-flex;align-items:center;gap:6px"><span style="font-size:16px;font-weight:900">' + count + '</span>' + label + '</div>';
}

function _diffTable_(rows, headers) {
  let h = '<table style="width:100%;border-collapse:collapse;font-size:13px"><thead><tr>';
  headers.forEach(hd => { h += '<th style="text-align:left;padding:6px 8px;border-bottom:1px solid rgba(255,255,255,.20);color:rgba(255,255,255,.70);font-weight:700">' + esc(hd) + '</th>'; });
  h += '</tr></thead><tbody>';
  rows.forEach(row => {
    h += '<tr>';
    Object.values(row).forEach(v => {
      h += '<td style="padding:6px 8px;border-bottom:1px solid rgba(255,255,255,.06);font-family:\'JetBrains Mono\',monospace">' + esc(v == null ? '' : v) + '</td>';
    });
    h += '</tr>';
  });
  h += '</tbody></table>';
  return h;
}

async function printPickListOnlyForOrder_(orderNumber) {
  const orderStr = String(orderNumber || '').trim();
  if (!orderStr) return;
  showToast('📥 Sending pick list for #' + orderStr + '…');
  try {
    const res = await printPickListOnly_(orderStr);
    if (res && res.ok) {
      showToast('✓ Pick list sent (#' + orderStr + ')');
    } else {
      showToast('⚠ Pick list: ' + ((res && res.error) || 'unknown'));
    }
  } catch (e) {
    showToast('⚠ Pick list error: ' + (e.message || e));
  }
}

// v10.559 — Zac flagged the Brother's auto-stapler grouping each
// order's pick list with the NEXT order's instructions during bulk
// print. Root cause: pick list and instructions were submitted as
// two separate PrintNode jobs ~milliseconds apart; the printer's
// time-window stapler treated the gap between A_pick and B_inst as
// shorter than the gap between A_inst and A_pick + A_pick alone (a
// single-page job didn't trigger a clean staple boundary).
//
// Fix: merge cover + instructions + pick list into ONE PDF per
// order, submit as a single PrintNode job. One job = one staple
// packet. No timing fragility.
async function printInstructionsAndPickListCombined_(orderNumber) {
  const orderStr = String(orderNumber || '').trim();
  if (!orderStr) return { ok: false, error: 'orderNumber required' };
  // Source the row from either cache (pipeline preferred — Orders tab).
  const cached = (typeof getCachedPipelineOrder === 'function')
    ? getCachedPipelineOrder(orderStr)
    : ((typeof _packQueueCache !== 'undefined' && Array.isArray(_packQueueCache))
        ? _packQueueCache.find(r => String(r.order_number) === orderStr) : null);
  if (!cached) return { ok: false, error: '#' + orderStr + ' not in cache — refresh first' };

  // Need both the instructions URL and pick list URL. Resolve the
  // instructions URL the same way printInstructionsLink_ does (INST-*
  // SKUs → InstructionsMap), but inline so we don't double-prompt the
  // UI banner.
  let instructionsUrl = '';
  try {
    const arr = JSON.parse(String(cached.sku_lines_json || '[]'));
    const instSkus = Array.isArray(arr)
      ? Array.from(new Set(arr.map(it => String((it && it.sku) || '').trim().toUpperCase()).filter(s => /^INST-/.test(s))))
      : [];
    if (instSkus.length) {
      const resolveRes = await groundApi('resolveInstructionsForSkus', { skus: instSkus });
      if (resolveRes && resolveRes.ok && Array.isArray(resolveRes.hits) && resolveRes.hits.length) {
        instructionsUrl = resolveRes.hits[0].pdf_url;
      }
    }
  } catch (e) { /* swallow — fall back to pick_list_pdf_url below */ }
  if (!instructionsUrl) instructionsUrl = String(cached.instructions_pdf_url || '').trim();

  const pickListUrl = String(cached.pick_list_pdf_url || '').trim();
  if (!instructionsUrl && !pickListUrl) {
    return { ok: false, error: 'no instructions or pick list URL for #' + orderStr };
  }

  try {
    showToast('🛠 Building combined packet for #' + orderStr + '…');
    const coverBytes = await buildPackCoverPagePdf_(cached);
    let instructionsBytes = null;
    let pickListBytes = null;
    if (instructionsUrl) {
      try { instructionsBytes = await packFetchPdfBytes_(instructionsUrl); }
      catch (e) { console.warn('combined: instructions fetch failed', e); }
    }
    if (pickListUrl) {
      try { pickListBytes = await packFetchPdfBytes_(pickListUrl); }
      catch (e) { console.warn('combined: pick list fetch failed', e); }
    }
    const merged = await mergeCoverInstructionsPickList_(coverBytes, instructionsBytes, pickListBytes);
    const base64 = uint8ToBase64_(merged);
    return await groundApi('printRawPackPdf', {
      orderNumber: orderStr,
      base64: base64,
      jobTitle: 'MBD Pack ' + orderStr + ' — combined (inst + pick list)',
    });
  } catch (e) {
    return { ok: false, error: 'combined print error: ' + (e.message || e) };
  }
}

// v10.559 — merge cover + instructions + pick list into one PDF.
// Blank duplex spacers between each so duplex output starts each
// document on a clean sheet. Pick list flows last so the operator
// can tear off the cover/instructions packet and keep the pick list
// for grab-and-pack reference if the workflow prefers.
async function mergeCoverInstructionsPickList_(coverBytes, instructionsBytes, pickListBytes) {
  const PDFLib = await loadPdfLib_();
  const out = await PDFLib.PDFDocument.create();
  if (coverBytes) {
    const cover = await PDFLib.PDFDocument.load(coverBytes);
    const pages = await out.copyPages(cover, cover.getPageIndices());
    pages.forEach(p => out.addPage(p));
    out.addPage([612, 792]);
  }
  if (instructionsBytes) {
    const inst = await PDFLib.PDFDocument.load(instructionsBytes, { ignoreEncryption: true });
    const pages = await out.copyPages(inst, inst.getPageIndices());
    pages.forEach(p => out.addPage(p));
    if (pickListBytes) out.addPage([612, 792]);
  }
  if (pickListBytes) {
    const pick = await PDFLib.PDFDocument.load(pickListBytes, { ignoreEncryption: true });
    const pages = await out.copyPages(pick, pick.getPageIndices());
    pages.forEach(p => out.addPage(p));
  }
  return await out.save();
}

// v10.543 / v10.560 — submit instructions (stapled) and pick list
// (NOT stapled) as two separate PrintNode jobs. v10.559 merged them
// into one stapled packet which Zac rejected: pick lists shouldn't
// be stapled to anything, including the instructions of their own
// order. v10.560 server-side printPickListPdfForOrder routes the
// pick list through PRINTNODE_PICK_LIST_PRINTER_ID (when set) so a
// separate non-stapling queue can handle it, and explicitly omits
// the duplex/staple options the instructions queue carries.
// v10.563 — print a hand-curated corrected pick list. Server-side
// printCorrectedPickList reads PickListCorrections + builds the PDF
// + submits to PrintNode. Button only renders when
// o.has_corrected_pick_list is true (driven by listPackingQueue /
// getOrderPipeline annotation).
async function printCorrectedPickList_(orderNumber) {
  const orderStr = String(orderNumber || '').trim();
  if (!orderStr) return;
  if (typeof showToast === 'function') {
    showToast('🖨 Sending corrected pick list for #' + orderStr + '…');
  }
  // v10.567 — resolve the MTO/stock cabinet's warehouse location from
  // the local cabinets[] master so the printed CABINETS section
  // shows "31600:MTO  📍 LOC" not just "31600:MTO". Falls back to
  // empty string if the cabinet isn't in master yet (server prints
  // without a location).
  let bedLocation = '';
  try {
    if (typeof cabinets !== 'undefined' && Array.isArray(cabinets) && typeof normCab === 'function') {
      const cab = cabinets.find(c => c && !c.deleted && normCab(c.cabinet) === normCab(orderStr));
      if (cab && cab.location) bedLocation = String(cab.location);
    }
  } catch (e) { /* leave blank */ }
  try {
    const res = await groundApi('printCorrectedPickList', {
      orderNumber: orderStr,
      bed_location: bedLocation,
    });
    if (res && res.ok) {
      if (typeof showToast === 'function') showToast('✓ Corrected pick list sent (#' + orderStr + ', job ' + (res.job_id || '?') + ') — opening backup tab in case PrintNode silently drops');
      // v10.569 — Zac 2026-06-15: PrintNode has been silently
      // canceling jobs on the stapler queue (or printing blank).
      // The server now always returns pdf_url too; open it in a
      // new tab so the operator can Ctrl-P from the browser as a
      // bulletproof fallback. Modal blockers are off on the iPad
      // PWA; window.open succeeds.
      if (res.pdf_url) {
        try { window.open(res.pdf_url, '_blank', 'noopener'); } catch (_) {}
      }
    } else {
      const err = (res && res.error) || 'unknown';
      if (typeof showToast === 'function') showToast('⚠ Corrected pick list failed: ' + err);
      console.warn('printCorrectedPickList_ failed:', res);
      // If server got far enough to build the PDF but PrintNode
      // submission failed, still open the PDF so the operator
      // can manually print.
      if (res && res.pdf_url) {
        try { window.open(res.pdf_url, '_blank', 'noopener'); } catch (_) {}
      }
    }
  } catch (e) {
    if (typeof showToast === 'function') showToast('⚠ Corrected pick list error: ' + (e.message || e));
  }
}

async function printInstructionsAndPickList_(orderNumber) {
  const orderStr = String(orderNumber || '').trim();
  if (!orderStr) return;
  showToast('📥 Sending instructions + pick list for #' + orderStr + '…');
  // v10.562 — Zac 2026-06-15: tapped this button for 32192/32217, got
  // pick lists only because the instructions path silently failed and
  // the toast only reported pick list status. Now we surface BOTH
  // outcomes and stack a banner for the failure cause.
  const [instRes, pickRes] = await Promise.all([
    printInstructionsLink_(orderStr),
    printPickListOnly_(orderStr),
  ]);
  const instOk = !!(instRes && instRes.ok);
  const pickOk = !!(pickRes && pickRes.ok);
  if (instOk && pickOk) {
    showToast('✓ Inst + Pick List sent (#' + orderStr + ')');
  } else if (!instOk && !pickOk) {
    showToast('⚠ Both failed (#' + orderStr + ') — see banner');
  } else if (!instOk) {
    showToast('⚠ Instructions FAILED, pick list sent (#' + orderStr + '): '
      + ((instRes && instRes.error) || 'unknown'));
  } else {
    showToast('⚠ Pick list FAILED, instructions sent (#' + orderStr + '): '
      + ((pickRes && pickRes.error) || 'unknown'));
  }
  // Surface a sticky banner for either failure so the operator can't
  // miss the silent half — same shape as the bulk-print failure banner.
  if (!instOk || !pickOk) {
    const instFails = !instOk ? ['#' + orderStr + ': ' + ((instRes && instRes.error) || 'unknown')] : [];
    const pickFails = !pickOk ? ['#' + orderStr + ': ' + ((pickRes && pickRes.error) || 'unknown')] : [];
    if (typeof _showBulkPrintFailureBanner_ === 'function') {
      _showBulkPrintFailureBanner_(instFails, pickFails);
    }
  }
}

async function printInstructionsLink_(orderNumber, presetSkus) {
  const orderStr = String(orderNumber);
  // v10.563 — packActionBanner lives inside the Pack tab DOM. When the
  // user taps Print Instructions from the Orders tab card, the Pack
  // tab is hidden and the banner is invisible — Zac saw no progress
  // feedback for 32217 today. Always announce via showToast (tab-
  // independent) at the start so the user knows the request fired.
  if (typeof showToast === 'function') {
    showToast('🔎 Looking up instructions for #' + orderStr + '…');
  }
  const banner = document.getElementById('packActionBanner');
  const bannerVisible = banner && banner.offsetParent !== null;
  const setBanner = (html, bg) => {
    if (!banner) return;
    banner.style.cssText = 'display:block;background:' + bg + ';color:#fff;padding:12px 16px;border-radius:8px;margin-bottom:10px;font-weight:700;letter-spacing:.3px;box-shadow:0 2px 8px rgba(0,0,0,.3)';
    banner.innerHTML = html;
    // v10.563 — also surface as a toast when the banner's host tab is
    // hidden (Orders tab → Pack tab DOM offscreen). Strip HTML so the
    // toast renders cleanly.
    if (!bannerVisible && typeof showToast === 'function') {
      const text = String(html).replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
      if (text) showToast(text);
    }
  };
  const hideBannerAfter = (ms) => {
    if (!banner) return;
    setTimeout(() => { if (banner) banner.style.display = 'none'; }, ms);
  };

  // Snapshot every Print button's text so we can restore after the
  // network round-trip without clobbering varied labels ("🖨 Print",
  // "🖨 Print Instructions", chip on INST-* row).
  const printBtns = document.querySelectorAll('button[onclick^="printInstructionsLink_(\\\''+orderStr+'\\\'"]');
  const flipFlight = () => {
    printBtns.forEach(b => {
      if (!b.dataset._origPrintText) b.dataset._origPrintText = b.innerHTML;
      b.disabled = true;
      b.style.opacity = '.7';
      b.innerHTML = '⏳ Sending…';
    });
  };
  const flipReset = () => {
    printBtns.forEach(b => {
      b.disabled = false;
      b.style.opacity = '1';
      if (b.dataset._origPrintText) b.innerHTML = b.dataset._origPrintText;
    });
  };
  const flipPrinted = () => {
    printBtns.forEach(b => {
      // v10.552 — Zac flagged a white-on-white "Print Instructions"
      // button after a successful print. Cause: the 3s "✓ Printed"
      // flash overwrote the inline background with '#00C853', then
      // restoring with `style.background = ''` cleared the inline
      // background ENTIRELY (including the original rgba(255,255,255,
      // .04)), letting the button fall back to the user-agent default
      // which is white-ish on Safari. The original color stayed light
      // → invisible text. Fix: snapshot the original inline values to
      // a dataset attribute on first flip and restore from there.
      if (!b.dataset._origBg) {
        b.dataset._origBg = b.style.background || '';
        b.dataset._origColor = b.style.color || '';
      }
      b.disabled = false;
      b.style.opacity = '1';
      b.innerHTML = '✓ Printed';
      b.style.background = '#00C853';
      b.style.color = '#0a0a0a';
      b.style.webkitTextFillColor = '#0a0a0a';
      setTimeout(() => {
        b.innerHTML = b.dataset._origPrintText || '🖨 Print';
        b.style.background = b.dataset._origBg || '';
        b.style.color = b.dataset._origColor || '';
        b.style.webkitTextFillColor = b.dataset._origColor || '';
      }, 3000);
    });
  };

  // v10.560 — Zac: bulk batch printed only pick lists for half the
  // orders (no instructions) because every early-return path here
  // was a bare `return` — the bulk caller's try/await + instOk++
  // succeeded because no exception fired. Now every exit path returns
  // an explicit { ok, error?, reason? } so bulk callers can detect
  // silent skips and report them.
  let row = (typeof _packQueueCache !== 'undefined')
    ? (_packQueueCache || []).find(r => String(r.order_number) === orderStr)
    : null;
  // Also try the pipeline cache so Orders-tab callers (where
  // _packQueueCache may be empty) don't hit a false "not in list".
  if (!row && typeof getCachedPipelineOrder === 'function') {
    row = getCachedPipelineOrder(orderStr);
  }
  if (!row) {
    setBanner('⚠ Order #' + orderStr + ' not in current Pack list — refresh first', 'linear-gradient(135deg,#c62828,#8d1e1e)');
    hideBannerAfter(5000);
    return { ok: false, error: '#' + orderStr + ' not in cache — refresh first' };
  }

  // Phase 1+2: resolve INST PDFs for this order. v10.564 — single
  // server call (`resolveInstructionsForOrder`) handles SKU gathering
  // AND map lookup. Server reads PackingQueue.sku_lines_json first,
  // falls back to Shopify line items if empty (synthetic gcal-only
  // orders), then runs the v10.561 trigger_skus reverse-map +
  // dedupe. Eliminates the "no SKUs found in sku_lines_json" silent
  // bail Zac hit on #32217.
  setBanner('🔎 Resolving instructions for #' + orderStr + '…', 'linear-gradient(135deg,#1565c0,#0d47a1)');
  flipFlight();
  let resolveRes;
  let instSkus = []; // populated below from server response, used by no-hits banner
  try {
    if (Array.isArray(presetSkus) && presetSkus.length) {
      // Picker-modal path: caller has already chosen the INST SKUs.
      instSkus = presetSkus.map(s => String(s || '').trim().toUpperCase()).filter(Boolean);
      resolveRes = await groundApi('resolveInstructionsForSkus', { skus: instSkus });
    } else {
      resolveRes = await groundApi('resolveInstructionsForOrder', { orderNumber: orderStr });
      instSkus = Array.isArray(resolveRes && resolveRes.skus_tried) ? resolveRes.skus_tried : [];
    }
  } catch (e) {
    setBanner('⚠ Lookup failed: ' + e.message, 'linear-gradient(135deg,#c62828,#8d1e1e)');
    hideBannerAfter(6000);
    flipReset();
    return { ok: false, error: 'InstructionsMap lookup threw: ' + (e.message || e), reason: 'lookup_threw' };
  }
  if (!resolveRes || !resolveRes.ok) {
    flipReset();
    // v10.564 — distinguish the no_skus_anywhere case (sku_lines_json
    // empty AND Shopify lookup also missing) from generic lookup
    // failures so the failure banner can point Zac at the right fix.
    const reason = (resolveRes && resolveRes.reason) || 'lookup_failed';
    const errMsg = (resolveRes && resolveRes.error) || 'unknown';
    if (reason === 'no_skus_anywhere') {
      setBanner('⚠ No SKUs found for #' + orderStr + ' — order has no PackingQueue row and Shopify returned no line items. Check the order exists in Shopify (<60 days old) or refresh the pipeline.',
        'linear-gradient(135deg,#c62828,#8d1e1e)');
      hideBannerAfter(12000);
    } else {
      setBanner('⚠ Lookup failed: ' + errMsg, 'linear-gradient(135deg,#c62828,#8d1e1e)');
      hideBannerAfter(6000);
    }
    return { ok: false, error: 'Instructions resolve failed (' + reason + '): ' + errMsg, reason: reason };
  }
  const hits = Array.isArray(resolveRes.hits) ? resolveRes.hits : [];
  const misses = Array.isArray(resolveRes.misses) ? resolveRes.misses : [];

  if (hits.length === 0) {
    flipReset();
    // v10.561 — misses now include every non-mapping SKU (BC1, slats,
    // hardware that isn't a bed identifier, etc.) so don't list them
    // all. Instead point Zac at the InstructionsMap with the order's
    // bed/bundle SKU front and center.
    const candidate = instSkus.find(s => /^(450\.|QBZ|SBLM|BOAZ|HLR|BC\d|MBD)/i.test(s)) || instSkus[0];
    setBanner(
      '⚠ No InstructionsMap entry triggers for #' + orderStr + ' (tried ' + instSkus.length + ' SKUs). '
      + 'Add a trigger_sku like <b>' + esc(candidate) + '</b> to the right INST row. '
      + 'Open <b>More → 📑 Instructions Map</b>.',
      'linear-gradient(135deg,#c62828,#8d1e1e)');
    hideBannerAfter(14000);
    return { ok: false, error: 'no InstructionsMap entry for any of: ' + instSkus.join(', '), reason: 'no_map_entry' };
  }

  // Phase 3a: 2+ hits → ask the packer (Zac: "if you find multiple
  // inst skus ask user what they want to do (print all or select one)").
  // Note: server dedupes by INST sku, so 2+ here means the order
  // genuinely has 2 distinct beds with distinct instructions.
  if (hits.length > 1) {
    flipReset();
    if (banner) banner.style.display = 'none';
    openInstructionsPrintPicker_(orderStr, hits, misses);
    // Picker is interactive; bulk caller can't wait for it, so
    // report this as a soft skip with a clear reason.
    return { ok: false, error: 'multiple INST hits (' + hits.map(h => h.sku).join(', ') + ') — picker opened', reason: 'multi_hit_picker' };
  }

  // Phase 3b: single hit → stamp + send straight to PrintNode.
  const hit = hits[0];
  const printOneRes = await _printOneResolvedInstruction_(orderStr, row, hit, { setBanner, hideBannerAfter, flipFlight, flipPrinted, flipReset });
  // v10.561 — `misses` now contains every order SKU that wasn't a
  // trigger (BC1, slats, finish, etc.); listing them as missing
  // map entries would be misleading noise. Suppress the secondary
  // banner. The misses array still travels in the return value.
  void misses;
  // _printOneResolvedInstruction_ doesn't return a result today; treat
  // reaching here as success for the single-hit happy path. (Real
  // PrintNode submission failures inside _printOneResolvedInstruction_
  // surface as their own banner.)
  return printOneRes && printOneRes.ok === false
    ? printOneRes
    : { ok: true, job_id: printOneRes && printOneRes.job_id };
}

// v10.314 — shared single-print path used by the single-hit branch
// of printInstructionsLink_ and by openInstructionsPrintPicker_.
async function _printOneResolvedInstruction_(orderStr, row, hit, ui) {
  ui.setBanner('🖨 Stamping cover + sending ' + hit.sku + ' for #' + orderStr + ' to PrintNode…', 'linear-gradient(135deg,#1565c0,#0d47a1)');
  ui.flipFlight();
  try {
    const res = await stampAndPrintPackInstructions_(row, hit.pdf_url, hit.sku);
    if (!res || !res.ok) {
      const why = (res && res.error) || 'unknown';
      ui.setBanner('⚠ Print failed for ' + hit.sku + ' on #' + orderStr + ': ' + why + ' — opening for AirPrint', 'linear-gradient(135deg,#ff9800,#e65100)');
      ui.hideBannerAfter(6000);
      ui.flipReset();
      try { await airPrintDrivePdf_(hit.pdf_url, orderStr + '-' + hit.sku + '.pdf'); } catch (e) {}
      return { ok: false, error: 'PrintNode submission failed: ' + why, reason: 'printnode_failed' };
    }
    ui.setBanner('✓ ' + hit.sku + ' for #' + orderStr + ' sent to PrintNode (job ' + (res.job_id || '?') + ')', 'linear-gradient(135deg,#00C853,#1A5C1A)');
    ui.hideBannerAfter(4000);
    try {
      row.instructions_printed_at = new Date().toISOString();
      if (typeof openPackDetail === 'function' && _packDetailOrderNumber === orderStr) openPackDetail(orderStr);
    } catch (e) { /* swallow */ }
    ui.flipPrinted();
    if (typeof refreshPackQueue === 'function') refreshPackQueue();
    return { ok: true, job_id: res.job_id };
  } catch (e) {
    ui.setBanner('⚠ Print error: ' + e.message, 'linear-gradient(135deg,#c62828,#8d1e1e)');
    ui.hideBannerAfter(6000);
    ui.flipReset();
    return { ok: false, error: 'stamp/print threw: ' + (e.message || e), reason: 'stamp_threw' };
  }
}

// v10.314 — multi-INST picker. Rare (only fires when an order has
// 2+ beds and therefore 2+ INST-* SKUs). Lets the packer print all
// in sequence (each as a separate job — easier to staple per-bed
// than to merge into one packet) or just one.
function openInstructionsPrintPicker_(orderStr, hits, misses) {
  // Tear down any prior picker so we don't stack modals.
  const prior = document.getElementById('instPrintPickerOverlay');
  if (prior) prior.remove();

  const overlay = document.createElement('div');
  overlay.id = 'instPrintPickerOverlay';
  overlay.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.65);z-index:10010;display:flex;align-items:center;justify-content:center;padding:20px';
  overlay.onclick = (ev) => { if (ev.target === overlay) overlay.remove(); };

  const modal = document.createElement('div');
  modal.style.cssText = 'background:#fff;color:#1a1a1a;max-width:560px;width:100%;border-radius:14px;padding:22px;box-shadow:0 10px 40px rgba(0,0,0,.5);max-height:88vh;overflow-y:auto';

  const rowsHtml = hits.map((h, idx) => {
    return ''
      + '<label style="display:flex;align-items:flex-start;gap:10px;padding:10px;border:1.5px solid #d0d0d0;border-radius:8px;margin-bottom:8px;cursor:pointer;background:#fafafa !important;color:#1a1a1a !important;-webkit-text-fill-color:#1a1a1a !important">'
      +   '<input type="checkbox" class="instPickerCheck" data-sku="' + esc(h.sku) + '" data-url="' + esc(h.pdf_url) + '" checked style="width:20px;height:20px;margin-top:2px;flex-shrink:0">'
      +   '<div style="flex:1;min-width:0">'
      +     '<div style="font-family:\'JetBrains Mono\',monospace;font-size:14px;font-weight:800;color:#003087 !important;-webkit-text-fill-color:#003087 !important">' + esc(h.sku) + '</div>'
      +     (h.description ? '<div style="font-size:12px;color:#555 !important;-webkit-text-fill-color:#555 !important;margin-top:2px">' + esc(h.description) + '</div>' : '')
      +     '<div style="font-size:11px;color:#888 !important;-webkit-text-fill-color:#888 !important;margin-top:3px;word-break:break-all">' + esc(h.pdf_url) + '</div>'
      +   '</div>'
      + '</label>';
  }).join('');

  const missHtml = (misses && misses.length)
    ? '<div style="margin-top:10px;padding:10px;background:#fff4e5 !important;border:1.5px dashed #ff9800;border-radius:8px;font-size:12px;color:#bf5700 !important;-webkit-text-fill-color:#bf5700 !important">⚠ No map entry for: <b>' + esc(misses.join(', ')) + '</b>. Open Instructions Map to add them.</div>'
    : '';

  modal.innerHTML = ''
    + '<div style="font-family:\'Barlow Condensed\',Arial,sans-serif;font-size:22px;font-weight:900;letter-spacing:1px;text-transform:uppercase;color:#1a1a1a !important;-webkit-text-fill-color:#1a1a1a !important;margin-bottom:6px">Multiple INST-* on #' + esc(orderStr) + '</div>'
    + '<div style="font-size:13px;color:#555 !important;-webkit-text-fill-color:#555 !important;margin-bottom:14px">Pick which to print (each goes as a separate print job so packets stack per-bed).</div>'
    + '<div id="instPickerList">' + rowsHtml + '</div>'
    + missHtml
    + '<div style="display:flex;gap:10px;margin-top:16px;flex-wrap:wrap">'
    +   '<button id="instPickerPrintBtn" style="flex:1;min-width:180px;padding:13px 16px;background:#003087;color:#fff !important;-webkit-text-fill-color:#fff !important;border:none;border-radius:8px;font-size:14px;font-weight:900;letter-spacing:.5px;text-transform:uppercase;cursor:pointer">🖨 Print Selected</button>'
    +   '<button id="instPickerCancelBtn" style="padding:13px 16px;background:#fff;color:#1a1a1a !important;-webkit-text-fill-color:#1a1a1a !important;border:1.5px solid #888;border-radius:8px;font-size:14px;font-weight:700;cursor:pointer">Cancel</button>'
    + '</div>';

  overlay.appendChild(modal);
  document.body.appendChild(overlay);

  modal.querySelector('#instPickerCancelBtn').onclick = () => overlay.remove();
  modal.querySelector('#instPickerPrintBtn').onclick = async () => {
    const picks = Array.from(modal.querySelectorAll('.instPickerCheck'))
      .filter(c => c.checked)
      .map(c => ({ sku: c.dataset.sku, pdf_url: c.dataset.url }));
    if (!picks.length) { showToast('Pick at least one SKU'); return; }
    overlay.remove();
    const row = (_packQueueCache || []).find(r => String(r.order_number) === orderStr);
    if (!row) { showToast('Order no longer in cache — refresh'); return; }
    const banner = document.getElementById('packActionBanner');
    const ui = {
      setBanner: (html, bg) => {
        if (!banner) return;
        banner.style.cssText = 'display:block;background:' + bg + ';color:#fff;padding:12px 16px;border-radius:8px;margin-bottom:10px;font-weight:700;letter-spacing:.3px;box-shadow:0 2px 8px rgba(0,0,0,.3)';
        banner.innerHTML = html;
      },
      hideBannerAfter: (ms) => { if (banner) setTimeout(() => { banner.style.display = 'none'; }, ms); },
      flipFlight: () => {},
      flipPrinted: () => {},
      flipReset: () => {},
    };
    for (let i = 0; i < picks.length; i++) {
      await _printOneResolvedInstruction_(orderStr, row, picks[i], ui);
      // brief pause between jobs so the packer can read the banner
      if (i < picks.length - 1) await new Promise(res => setTimeout(res, 800));
    }
  };
}

// v10.314 — alias retained so any straggling callers still resolve.
// All print-instructions paths now route through printInstructionsLink_.
async function printOneInstruction(orderNumber) {
  return printInstructionsLink_(orderNumber);
}

// v10.292 — manager-PIN override: mark an order packed without scan
// verification, for cases where there's no pick-list available (RMK
// orders, freshly bootstrapped rows with no Drive URL, etc.). Uses
// the existing markPackJobComplete endpoint with manager_pin which
// bypasses the "checking + checker-scans-complete" preconditions.
async function manualMarkPackedNoSku_(orderNumber) {
  if (!confirm('Mark order #' + orderNumber + ' as packed without scan verification?\n\nUse this only when there is no pick list to scan against (e.g. a remake order or a manual pack). Manager PIN required.')) return;
  const pin = (typeof promptManagerPin_ === 'function')
    ? promptManagerPin_('manual mark packed for ' + orderNumber)
    : prompt('Manager PIN:');
  if (!pin) return;
  try {
    const res = await groundApi('markPackJobComplete', {
      orderNumber: String(orderNumber),
      manager_pin: pin,
      packedBy: (typeof getPackDeviceName_ === 'function' ? getPackDeviceName_() : 'manual-override'),
    });
    if (!res || !res.ok) {
      if (res && /pin/i.test(res.error || '')) {
        if (typeof clearManagerPin_ === 'function') clearManagerPin_();
      }
      showToast('Mark failed: ' + ((res && res.error) || 'unknown'));
      return;
    }
    showToast('✓ #' + orderNumber + ' marked packed (manual override)');
    if (typeof refreshPackQueue === 'function') await refreshPackQueue();
    const cache = (typeof _packQueueCache !== 'undefined' && _packQueueCache) || [];
    const row = cache.find(r => String(r.order_number) === String(orderNumber));
    if (row && typeof openPackDetail === 'function') openPackDetail(orderNumber);
  } catch (err) {
    showToast('Mark error: ' + err.message);
  }
}

function bumpPackSku(orderNumber, idx, delta) {
  const state = _packScanState[orderNumber];
  if (!state || !state.skus[idx]) return;
  const s = state.skus[idx];
  const prev = s.scanned;
  // Optimistic local update so the tap feels instant.
  s.scanned = Math.max(0, s.scanned + delta);
  renderPackSkuList_(orderNumber);

  const bumpAction = _packActivePhase === 'checker' ? 'recordPackCheckScan' : 'recordPackScan';
  packEnqueue_(orderNumber, async () => {
    try {
      const res = await groundApi(bumpAction, {
        orderNumber: orderNumber,
        scannedSku: s.sku,
        manualAdjustment: true,
        delta: delta,
        deviceId: getPackDeviceId_(),
      });
      if (!res || !res.ok) {
        if (_packScanState[orderNumber] && _packScanState[orderNumber].skus[idx]) {
          _packScanState[orderNumber].skus[idx].scanned = prev;
          if (_packDetailOrderNumber === orderNumber) renderPackSkuList_(orderNumber);
        }
        showToast('Adjustment failed: ' + ((res && res.error) || 'unknown'));
        return;
      }
      const cached = _packQueueCache.find(r => String(r.order_number) === String(orderNumber));
      if (cached) {
        if (_packActivePhase === 'checker') cached.checker_scanned_json = res.scanned_json;
        else cached.scanned_json = res.scanned_json;
      }
      // Authoritative apply for manual ± because the user's explicit intent
      // is the new count (not max-merge — a − tap should be able to
      // decrement past optimistic increments from concurrent scans).
      // v10.343 — only update SKUs the server actually returned. Stale
      // server responses that DIDN'T include the bumped SKU were zeroing
      // it out, causing the "looks like it undoes for 10 seconds"
      // flicker Zac flagged in v10.342. New rule: hasOwnProperty check.
      let serverByScannedSku = {};
      try {
        const arr = JSON.parse(res.scanned_json || '[]');
        if (Array.isArray(arr)) arr.forEach(x => { serverByScannedSku[String(x.sku || '').trim()] = Number(x.scanned) || 0; });
      } catch(e) {}
      const localState = _packScanState[orderNumber];
      if (localState) {
        localState.skus.forEach(x => {
          if (!serverByScannedSku.hasOwnProperty(x.sku)) return; // keep optimistic
          if (x.sku === s.sku) x.scanned = serverByScannedSku[x.sku];
          else x.scanned = Math.max(x.scanned, serverByScannedSku[x.sku]);
        });
      }
      if (_packDetailOrderNumber === orderNumber) renderPackSkuList_(orderNumber);
    } catch (err) {
      if (_packScanState[orderNumber] && _packScanState[orderNumber].skus[idx]) {
        _packScanState[orderNumber].skus[idx].scanned = prev;
        if (_packDetailOrderNumber === orderNumber) renderPackSkuList_(orderNumber);
      }
      showToast('Adjustment error: ' + err.message);
    }
  });
}

function handlePackScanSubmit() {
  const input = document.getElementById('packScanInput');
  if (!input) return;
  const code = input.value.trim();
  input.value = '';
  if (!code) return;
  processPackScan_(code);
  input.focus();
}

function processPackScan_(code) {
  if (!_packDetailOrderNumber) return;
  const orderNumber = _packDetailOrderNumber;
  const state = _packScanState[orderNumber];
  if (!state || !state.skus.length) {
    showToast('No SKU list loaded — upload a pick list first');
    return;
  }

  // Optimistic local match is applied immediately so the UI feels
  // instant; the actual server roundtrip is queued so it can't race
  // with a follow-up scan's server roundtrip.
  // v10.443 — match priority:
  //   1. exact barcode match (when sku_lines has a barcode field
  //      distinct from sku, written by v10.437 native upgrade)
  //   2. exact sku match
  //   3. sku prefix match (≥4 chars)
  const codeNorm = packNorm_(code);
  let optimisticIdx = state.skus.findIndex(s => s.barcode && packNorm_(s.barcode) === codeNorm);
  if (optimisticIdx < 0) {
    optimisticIdx = state.skus.findIndex(s => packNorm_(s.sku) === codeNorm);
  }
  if (optimisticIdx < 0) {
    optimisticIdx = state.skus.findIndex(s => packNorm_(s.sku).startsWith(codeNorm) && codeNorm.length >= 4);
  }
  if (optimisticIdx >= 0) {
    const s = state.skus[optimisticIdx];
    s.scanned = Math.min(s.qty + 5, s.scanned + 1);
    renderPackSkuList_(orderNumber);
  }

  const scanAction = _packActivePhase === 'checker' ? 'recordPackCheckScan' : 'recordPackScan';
  packEnqueue_(orderNumber, async () => {
    try {
      const res = await groundApi(scanAction, {
        orderNumber: orderNumber,
        scannedSku: code,
        deviceId: getPackDeviceId_(),
      });
      if (!res || !res.ok) {
        if (optimisticIdx >= 0 && _packScanState[orderNumber]) {
          _packScanState[orderNumber].skus[optimisticIdx].scanned =
            Math.max(0, _packScanState[orderNumber].skus[optimisticIdx].scanned - 1);
          if (_packDetailOrderNumber === orderNumber) renderPackSkuList_(orderNumber);
        }
        // v10.401 — §7 wrong-SKU "did you mean" modal replaces the silent toast
        // when the scan didn't match any sku on the order. Server-side rejections
        // for other reasons (sku not in order's lines) get the modal; alias/box
        // rejections still surface as toasts (different error shape).
        const errStr = String((res && res.error) || '').toLowerCase();
        const noMatch = /not on this order|no match|sku.*not found|unknown sku|reject/i.test(errStr) || optimisticIdx < 0;
        if (noMatch) {
          _showWrongSkuModal_(code, orderNumber);
        } else {
          showToast(((res && res.error) || 'Scan rejected'));
        }
        return;
      }
      // v10.401 — scan match: light haptic + success tone + activity ping.
      try { if (navigator.vibrate) navigator.vibrate(18); } catch (eVib) {}
      _packPlayScanTone_(true);
      _packMarkScanActivity_();
      // Merge: keep counts at max(local, server) so an earlier server
      // response from a stale scan can't overwrite a later optimistic
      // increment. Once the whole queue drains, the two converge.
      const cached = _packQueueCache.find(r => String(r.order_number) === String(orderNumber));
      if (cached) {
        if (_packActivePhase === 'checker') cached.checker_scanned_json = res.scanned_json;
        else cached.scanned_json = res.scanned_json;
      }
      let serverByScannedSku = {};
      try {
        const arr = JSON.parse(res.scanned_json || '[]');
        if (Array.isArray(arr)) arr.forEach(s => { serverByScannedSku[String(s.sku || '').trim()] = Number(s.scanned) || 0; });
      } catch(e) {}
      const localState = _packScanState[orderNumber];
      if (localState) {
        localState.skus.forEach(s => {
          const serverCount = serverByScannedSku[s.sku] || 0;
          s.scanned = Math.max(s.scanned, serverCount);
        });
      }
      if (_packDetailOrderNumber === orderNumber) renderPackSkuList_(orderNumber);
      if (navigator.vibrate) navigator.vibrate(res.scanned >= res.qty ? [60, 30, 60] : 40);
      if (res.kind === 'box_alias' || res.kind === 'parent_alias') {
        showToast('✓ ' + res.sku + ' via alias "' + res.scanned_alias + '" — ' + res.scanned + '/' + res.qty);
      } else if (res.scanned >= res.qty) {
        showToast('✓ ' + res.sku + ' complete (' + res.scanned + '/' + res.qty + ')');
      }
    } catch (err) {
      if (optimisticIdx >= 0 && _packScanState[orderNumber]) {
        _packScanState[orderNumber].skus[optimisticIdx].scanned =
          Math.max(0, _packScanState[orderNumber].skus[optimisticIdx].scanned - 1);
        if (_packDetailOrderNumber === orderNumber) renderPackSkuList_(orderNumber);
      }
      showToast('Scan error: ' + err.message);
    }
  });
}

// Phase-aware reset: hits whichever scan column is active.
async function resetActivePackScansForOrder(orderNumber) {
  const action = _packActivePhase === 'checker' ? 'resetPackCheckScans' : 'resetPackScans';
  return resetPackScansViaAction_(orderNumber, action);
}

async function resetPackScansViaAction_(orderNumber, action) {
  if (!confirm('Reset scans for order ' + orderNumber + '? (Photos, claim, and the other phase\'s scans are preserved.)')) return;
  try {
    const res = await groundApi(action, { orderNumber: orderNumber, deviceId: getPackDeviceId_() });
    if (!res || !res.ok) {
      showToast('Reset failed: ' + ((res && res.error) || 'unknown'));
      return;
    }
    const cached = _packQueueCache.find(r => String(r.order_number) === String(orderNumber));
    if (cached) {
      if (_packActivePhase === 'checker') cached.checker_scanned_json = '';
      else cached.scanned_json = '';
    }
    delete _packScanState[orderNumber];
    if (cached) {
      const seedJson = (_packActivePhase === 'checker') ? cached.checker_scanned_json : cached.scanned_json;
      getPackScanState_(orderNumber, cached.sku_lines_json, seedJson);
    }
    renderPackSkuList_(orderNumber);
    showToast('Scans reset');
  } catch (err) {
    showToast('Reset error: ' + err.message);
  }
}

async function confirmReadyForCheck(orderNumber) {
  // v10.402 — spec § 9 second-person handoff. Instead of confirm-dialog +
  // close-and-find-the-order-from-another-device, we go directly to a hero
  // overlay on this device. The packer literally hands the phone to anyone
  // else, who taps Confirm Pack. That one button does claim + complete in
  // sequence on the server, blocked if the confirming device === packer.
  const state = _packScanState[orderNumber];
  let unscanned = 0;
  if (state) state.skus.forEach(s => { if (s.scanned < s.qty) unscanned += (s.qty - s.scanned); });
  if (unscanned > 0) {
    const proceed = confirm(unscanned + ' SKU unit' + (unscanned === 1 ? '' : 's') + ' still unscanned.\n\nHand off anyway? (the second person can still spot-check.)');
    if (!proceed) return;
  }
  return _guardedAction_({
    key: 'readyForCheck:' + orderNumber,
    btnSelector: 'button[onclick="confirmReadyForCheck(\'' + orderNumber + '\')"]',
    busyText: '⏳ Handing off…',
    action: async () => {
      try {
        const res = await groundApi('markPackJobReadyForCheck', { orderNumber: orderNumber, deviceId: getPackDeviceId_() });
        if (!res || !res.ok) {
          let msg = (res && res.error) || 'unknown';
          if (res && res.pending && res.pending.length) {
            msg += '\nUnscanned: ' + res.pending.map(p => p.sku + ' (' + p.scanned + '/' + p.qty + ')').join(', ');
          }
          showToast('Ready-for-check failed: ' + msg);
          return;
        }
        // Patch local cache so handoff overlay reads the latest status without
        // an extra refresh roundtrip.
        const cached = _packQueueCache.find(r => String(r.order_number) === String(orderNumber));
        if (cached) cached.status = 'ready_for_check';
        if (typeof _showSecondPersonHandoff_ === 'function') {
          _showSecondPersonHandoff_(orderNumber);
        } else {
          showToast('Handed off to checker ✓');
          closePackDetail();
          await refreshPackQueue();
        }
      } catch (err) {
        showToast('Ready-for-check error: ' + err.message);
      }
    },
  });
}

async function claimPackCheck(orderNumber) {
  return _guardedAction_({
    key: 'claimPackCheck:' + orderNumber,
    btnSelector: 'button[onclick="claimPackCheck(\'' + orderNumber + '\')"]',
    busyText: '⏳ Claiming check…',
    action: async () => {
      try {
        const res = await groundApi('claimPackCheckJob', {
          orderNumber: orderNumber,
          deviceId: getPackDeviceId_(),
          checkerName: localStorage.getItem('mbd_ground_packer') || '',
        });
        if (!res || !res.ok) {
          showToast('Could not start check: ' + ((res && res.error) || 'unknown'));
          return;
        }
        showToast('Checking order ' + orderNumber);
        await refreshPackQueue();
        openPackDetail(orderNumber);
      } catch (err) {
        showToast('Check claim error: ' + err.message);
      }
    },
  });
}

async function releasePackCheck(orderNumber) {
  if (!confirm('Release the check on order ' + orderNumber + '? Status goes back to "ready for check" so another checker can pick it up.')) return;
  return _guardedAction_({
    key: 'releasePackCheck:' + orderNumber,
    btnSelector: 'button[onclick="releasePackCheck(\'' + orderNumber + '\')"]',
    busyText: '⏳ Releasing…',
    action: async () => {
      try {
        const res = await groundApi('releasePackCheckJob', { orderNumber: orderNumber, deviceId: getPackDeviceId_() });
        if (!res || !res.ok) {
          showToast('Release failed: ' + ((res && res.error) || 'unknown'));
          return;
        }
        showToast('Released — order ' + orderNumber + ' is back to "ready for check"');
        if (typeof closePackDetail === 'function') closePackDetail();
        await refreshPackQueue();
      } catch (err) {
        showToast('Release error: ' + err.message);
      }
    },
  });
}

// In-memory cache of the manager PIN — saved after one successful
// manager action, expires 10 min later. Avoids re-typing the PIN for
// every batch the same manager runs in one session. Not persisted to
// localStorage (would defeat the security premise).
let _packManagerPin = null;
let _packManagerPinExpiresAt = 0;

function getCachedManagerPin_() {
  if (_packManagerPin && Date.now() < _packManagerPinExpiresAt) return _packManagerPin;
  return null;
}

// v10.475 — TTL bumped 10 → 30 min per Zac: "i shouldn't have to put
// in the pin again for like 30 minutes". Same cache now serves Pack
// AND Ground manager actions (e.g. managerCheckOff on Ground boxes).
function cacheManagerPin_(pin) {
  _packManagerPin = pin;
  _packManagerPinExpiresAt = Date.now() + 30 * 60 * 1000;
}

// v10.468 — Resolve a PrintNode printer_id to "Name @ Host" using the
// cached selector map (populated when the printer selector is opened).
// Falls back to "#id" when the map is empty or misses the id.
function _printerLabelById_(id) {
  const n = Number(id) || 0;
  if (!n) return '';
  try {
    const raw = localStorage.getItem('printNodePrintersMap');
    if (!raw) return '#' + n;
    const map = JSON.parse(raw) || {};
    const p = map[String(n)];
    if (!p) return '#' + n + ' (unknown — refresh printer list)';
    return '#' + n + ' · ' + (p.name || '?') + (p.host ? ' @ ' + p.host : '');
  } catch (_e) { return '#' + n; }
}

function clearManagerPin_() {
  _packManagerPin = null;
  _packManagerPinExpiresAt = 0;
}

function promptManagerPin_(reason) {
  const cached = getCachedManagerPin_();
  if (cached) return cached;
  const pin = prompt('Manager PIN' + (reason ? ' (' + reason + ')' : '') + ':');
  if (pin == null) return null;
  const trimmed = pin.trim();
  if (!trimmed) return null;
  cacheManagerPin_(trimmed);
  return trimmed;
}

function showPackBanner_(text, color) {
  const banner = document.getElementById('packActionBanner');
  if (!banner) return;
  banner.style.cssText = 'display:block;background:'+color+'1a;border:1px solid '+color+'72;border-radius:10px;padding:14px 16px;margin-bottom:10px;color:'+color+';font-family:\'Barlow Condensed\',Arial,sans-serif;font-size:18px;font-weight:900;letter-spacing:1px;text-transform:uppercase';
  banner.textContent = text;
  clearTimeout(showPackBanner_._t);
  showPackBanner_._t = setTimeout(() => { banner.style.display = 'none'; }, 6000);
}

// pdf-lib lazy loader — only fetched when "Print All" is tapped so
// the ~300KB doesn't load on every page open.
async function loadPdfLib_() {
  if (window.PDFLib) return window.PDFLib;
  await new Promise((resolve, reject) => {
    const s = document.createElement('script');
    s.src = 'https://cdn.jsdelivr.net/npm/pdf-lib@1.17.1/dist/pdf-lib.min.js';
    s.onload = resolve;
    s.onerror = () => reject(new Error('pdf-lib failed to load — check your network'));
    document.head.appendChild(s);
  });
  if (!window.PDFLib) throw new Error('pdf-lib loaded but not on window');
  return window.PDFLib;
}

// JsBarcode lazy loader — Code 128 barcode generation for the stamped
// cover page. Renders to a canvas, which we then snapshot as a PNG and
// embed in the cover via pdf-lib.
async function loadJsBarcode_() {
  if (window.JsBarcode) return window.JsBarcode;
  await new Promise((resolve, reject) => {
    const s = document.createElement('script');
    s.src = 'https://cdn.jsdelivr.net/npm/jsbarcode@3.11.5/dist/JsBarcode.all.min.js';
    s.onload = resolve;
    s.onerror = () => reject(new Error('JsBarcode failed to load'));
    document.head.appendChild(s);
  });
  if (!window.JsBarcode) throw new Error('JsBarcode loaded but not on window');
  return window.JsBarcode;
}

// Generate a Code 128 barcode of the order number as a PNG data URL.
function makeOrderBarcodePng_(orderNumber) {
  const canvas = document.createElement('canvas');
  JsBarcode(canvas, String(orderNumber), {
    format: 'CODE128',
    width: 3,
    height: 80,
    displayValue: true,
    fontSize: 22,
    margin: 10,
    background: '#ffffff',
    lineColor: '#000000',
  });
  return canvas.toDataURL('image/png');
}

// Build a one-page cover PDF (as Uint8Array) with order # huge at the
// top, customer abbrev + state, ship date, customer name + address,
// and a Code 128 barcode at the bottom. Prepends to the instructions
// PDF before sending to PrintNode. Page is Letter (612×792 pt).
// v10.536 — Cover-page "Cabinet: …" line resolver. Stock orders match
// a D###/STK###/C###/E### token in task_line or cal_label; MTO orders
// (no stock token) get a literal "{orderNumber}: MTO" label. Mirrors
// the regex used by _resolveOrderCabinets_ for Pack-Today cards so a
// packer sees the same identifier on the printed cover as on screen.
function _resolvePackCoverCabinetLine_(row) {
  if (!row) return '';
  const orderNum = String(row.order_number || '').trim();
  const tline = String(row.task_line || '') + ' ' + String(row.cal_label || '');
  const matches = tline.match(/\b(?:D|STK|C|E)\d{2,4}(?:-[A-Z0-9]+)?\b/gi);
  if (matches && matches.length) {
    const uniq = [...new Set(matches.map(s => s.toUpperCase()))];
    return 'Cabinet: ' + uniq.join(', ');
  }
  return orderNum ? 'Cabinet: ' + orderNum + ': MTO' : '';
}

async function buildPackCoverPagePdf_(row) {
  const PDFLib = await loadPdfLib_();
  await loadJsBarcode_();
  const cover = await PDFLib.PDFDocument.create();
  const page = cover.addPage([612, 792]);
  const bold = await cover.embedFont(PDFLib.StandardFonts.HelveticaBold);
  const reg = await cover.embedFont(PDFLib.StandardFonts.Helvetica);
  const black = PDFLib.rgb(0, 0, 0);
  const dim = PDFLib.rgb(0.35, 0.35, 0.35);

  // Huge order number, centered horizontally near the top.
  const orderText = '#' + String(row.order_number || '?');
  const orderSize = 140;
  const orderWidth = bold.widthOfTextAtSize(orderText, orderSize);
  page.drawText(orderText, {
    x: (612 - orderWidth) / 2,
    y: 600,
    size: orderSize,
    font: bold,
    color: black,
  });

  // v10.536 — Cabinet line directly below the order#. For stock orders
  // it's the cabinet ID parsed from task_line/cal_label (D###/C###/etc).
  // For MTO orders (no stock-ID match), it's "{orderNumber}: MTO".
  const cabLine = _resolvePackCoverCabinetLine_(row);
  if (cabLine) {
    const cabSize = 24;
    const cabWidth = bold.widthOfTextAtSize(cabLine, cabSize);
    page.drawText(cabLine, {
      x: Math.max(40, (612 - cabWidth) / 2),
      y: 555,
      size: Math.min(cabSize, (612 - 80) * cabSize / Math.max(cabWidth, cabSize)),
      font: bold,
      color: black,
      maxWidth: 612 - 80,
    });
  }

  // Second line: the task line (e.g. "31875 OSB (D123 QLHW81) -BKS MN CC")
  // gives us customer abbrev, lot, SKU, state, carrier at a glance.
  const taskLine = String(row.task_line || '').trim();
  if (taskLine) {
    const taskSize = 28;
    const taskWidth = bold.widthOfTextAtSize(taskLine, taskSize);
    page.drawText(taskLine, {
      x: Math.max(40, (612 - taskWidth) / 2),
      y: 510,
      size: Math.min(taskSize, (612 - 80) * taskSize / Math.max(taskWidth, taskSize)),
      font: bold,
      color: black,
      maxWidth: 612 - 80,
    });
  }

  // Ship date — third line.
  if (row.ship_date) {
    const sd = 'SHIP: ' + row.ship_date;
    const sdSize = 22;
    const sdWidth = bold.widthOfTextAtSize(sd, sdSize);
    page.drawText(sd, {
      x: (612 - sdWidth) / 2,
      y: 470,
      size: sdSize,
      font: bold,
      color: black,
    });
  }

  // Customer name + address as a small block in the middle.
  const cust = String(row.customer_name || '').trim();
  const addr = String(row.customer_address || '').trim();
  let y = 410;
  if (cust) {
    page.drawText(cust, { x: 40, y: y, size: 16, font: reg, color: black, maxWidth: 532 });
    y -= 22;
  }
  if (addr) {
    // Wrap manually at ~70 chars.
    const lines = [];
    let buf = '';
    addr.split(/\s+/).forEach(w => {
      if ((buf + ' ' + w).trim().length > 70) { if (buf) lines.push(buf); buf = w; }
      else buf = (buf ? buf + ' ' : '') + w;
    });
    if (buf) lines.push(buf);
    lines.forEach(l => {
      page.drawText(l, { x: 40, y: y, size: 14, font: reg, color: dim });
      y -= 18;
    });
  }
  if (row.customer_phone) {
    page.drawText(String(row.customer_phone), { x: 40, y: y, size: 14, font: reg, color: dim });
    y -= 18;
  }

  // Barcode at the bottom — scannable by the iPad's keyboard-wedge scanner.
  try {
    const barcodeDataUrl = makeOrderBarcodePng_(row.order_number);
    const pngBytes = await fetch(barcodeDataUrl).then(r => r.arrayBuffer());
    const png = await cover.embedPng(pngBytes);
    const targetWidth = 400;
    const scale = targetWidth / png.width;
    const targetHeight = png.height * scale;
    page.drawImage(png, {
      x: (612 - targetWidth) / 2,
      y: 80,
      width: targetWidth,
      height: targetHeight,
    });
  } catch (err) {
    console.warn('barcode embed failed:', err);
    // Fallback: draw the order number plain
    page.drawText('Order ' + String(row.order_number), {
      x: 40, y: 100, size: 18, font: bold, color: black,
    });
  }

  // Footer with timestamp + a packer note
  const ts = new Date().toLocaleString();
  page.drawText('Printed ' + ts, { x: 40, y: 40, size: 9, font: reg, color: dim });
  page.drawText('Scan barcode at packing station to open order', { x: 320, y: 40, size: 9, font: reg, color: dim });

  return await cover.save();
}

// v10.539 — Jurgen install orders: print just the order#/cabinet
// cover page, no instructions PDF appended. The cover carries
// everything Jurgen needs (order#, Cabinet line, ship date, customer
// block, scannable barcode); Jurgen has his own assembly process and
// doesn't read MBD's instructions sheets.
async function printJurgenCoverOnly_(orderNumber) {
  const key = String(orderNumber || '').trim();
  if (!key) return;
  const cached = (typeof getCachedPipelineOrder === 'function')
    ? getCachedPipelineOrder(key)
    : (Array.isArray(_packQueueCache) ? _packQueueCache.find(r => String(r.order_number) === key) : null);
  if (!cached) { showToast('#' + key + ' not loaded — refresh first'); return; }
  try {
    showToast('Building cover for #' + key + '…');
    const coverBytes = await buildPackCoverPagePdf_(cached);
    const base64 = uint8ToBase64_(coverBytes);
    const res = await groundApi('printRawPackPdf', {
      orderNumber: key,
      base64: base64,
      jobTitle: 'MBD Pack ' + key + ' — Jurgen cover only',
    });
    if (res && res.ok) {
      showToast('Cover sent to printer (#' + key + ')');
    } else {
      showToast('Cover print failed: ' + ((res && res.error) || 'unknown'));
    }
  } catch (e) {
    showToast('Cover print error: ' + (e.message || e));
  }
}

// Take instructions PDF bytes, prepend the generated cover + a blank
// page (so duplex printing lands the instructions' original first page
// on the front of sheet 2, not the back of the cover sheet), return
// the combined bytes.
async function prependCoverToPdf_(coverBytes, instructionsBytes) {
  const PDFLib = await loadPdfLib_();
  const out = await PDFLib.PDFDocument.create();
  const cover = await PDFLib.PDFDocument.load(coverBytes);
  const instructions = await PDFLib.PDFDocument.load(instructionsBytes, { ignoreEncryption: true });
  const coverPages = await out.copyPages(cover, cover.getPageIndices());
  coverPages.forEach(p => out.addPage(p));
  // Blank duplex spacer. Sized to match the cover so the printer
  // doesn't reflow / scale anything. Letter (612×792 pt).
  out.addPage([612, 792]);
  const instructionPages = await out.copyPages(instructions, instructions.getPageIndices());
  instructionPages.forEach(p => out.addPage(p));
  return await out.save();
}

// Base64-encode a Uint8Array — avoiding String.fromCharCode.apply spread
// blow-up on large arrays.
function uint8ToBase64_(bytes) {
  let bin = '';
  const chunk = 0x8000;
  for (let i = 0; i < bytes.length; i += chunk) {
    bin += String.fromCharCode.apply(null, bytes.subarray(i, i + chunk));
  }
  return btoa(bin);
}

// Stamp + print one order's instructions. Fetches the given PDF URL
// (via orchestrator passthrough), generates the cover, prepends, sends
// base64 to printRawPackPdf. Returns the server's response object.
//
// v10.314 — accepts an explicit URL so the caller resolves which PDF
// to print (typically via the InstructionsMap SKU lookup). The legacy
// row.instructions_pdf_url field is no longer used as a fallback —
// resolution is the caller's responsibility.
async function stampAndPrintPackInstructions_(row, urlOverride, jobTitleSuffix) {
  const url = urlOverride || row.instructions_pdf_url || row.pick_list_pdf_url;
  if (!url) throw new Error('no PDF URL for ' + row.order_number);
  const instructionsBytes = await packFetchPdfBytes_(url);
  const coverBytes = await buildPackCoverPagePdf_(row);
  const combined = await prependCoverToPdf_(coverBytes, instructionsBytes);
  const base64 = uint8ToBase64_(combined);
  return await groundApi('printRawPackPdf', {
    orderNumber: row.order_number,
    base64: base64,
    jobTitle: 'MBD Pack ' + row.order_number + (jobTitleSuffix ? ' — ' + jobTitleSuffix : ''),
  });
}

// Fetch a Drive PDF via the orchestrator (passes auth so PII-restricted
// PDFs work) and return raw bytes as Uint8Array.
async function packFetchPdfBytes_(driveUrl) {
  const res = await groundApi('fetchPackPickListPdf', { driveUrl: driveUrl });
  if (!res || !res.ok || !res.base64) {
    throw new Error((res && res.error) || 'orchestrator returned no bytes for ' + driveUrl);
  }
  const raw = atob(res.base64);
  const bytes = new Uint8Array(raw.length);
  for (let i = 0; i < raw.length; i++) bytes[i] = raw.charCodeAt(i);
  return bytes;
}

// Open a Drive PDF in a new tab for AirPrint. Fetches via orchestrator
// (since the PDF carries customer PII and isn't publicly shared), wraps
// as a Blob URL, opens. Safari → Share sheet → Print → AirPrint Brother.
async function airPrintDrivePdf_(driveUrl, suggestedFilename) {
  const bytes = await packFetchPdfBytes_(driveUrl);
  const blob = new Blob([bytes], { type: 'application/pdf' });
  const url = URL.createObjectURL(blob);
  const w = window.open(url, '_blank');
  if (!w) {
    // Popup blocked — surface a tappable link.
    showToast('Allow popups, then tap Print again');
  }
  // Don't revoke immediately — Safari may still be loading. Revoke after a
  // minute; if the user prints faster than that, the blob will be cached.
  setTimeout(() => URL.revokeObjectURL(url), 60000);
}

// Ensure a row has its instructions_pdf_url populated. If it's missing,
// fetch the pick-list PDF via the orchestrator, parse it with PDF.js,
// extract the first drive.google.com hyperlink (the INST-* link), and
// persist via setPackInstructionsUrl. Idempotent — early-exits if the
// URL is already there. Returns the URL or empty string on failure.
async function ensurePackInstructionsUrl_(orderNumber) {
  const row = _packQueueCache.find(r => String(r.order_number) === String(orderNumber));
  if (!row) return '';
  if (row.instructions_pdf_url) return row.instructions_pdf_url;
  if (!row.pick_list_pdf_url) return '';

  const parsed = await (async () => {
    try {
      const res = await groundApi('fetchPackPickListPdf', { driveUrl: row.pick_list_pdf_url });
      if (!res || !res.ok || !res.base64) throw new Error((res && res.error) || 'orchestrator fetch failed');
      const raw = atob(res.base64);
      const bytes = new Uint8Array(raw.length);
      for (let i = 0; i < raw.length; i++) bytes[i] = raw.charCodeAt(i);
      return await packParsePdfBuffer_(bytes.buffer);
    } catch (err) {
      console.warn('ensurePackInstructionsUrl_(' + orderNumber + ') parse failed:', err.message);
      return null;
    }
  })();

  if (!parsed || !parsed.instructionsPdfUrl) return '';

  try {
    const res = await groundApi('setPackInstructionsUrl', {
      orderNumber: orderNumber,
      url: parsed.instructionsPdfUrl,
    });
    if (res && res.ok) {
      row.instructions_pdf_url = parsed.instructionsPdfUrl;
      return parsed.instructionsPdfUrl;
    }
  } catch (e) { /* swallow */ }
  return '';
}

// v10.92 (task #63, Zac): when the instructions link can't be
// auto-extracted from the pick-list PDF, the packer was stuck —
// nothing prompted for it and every print re-attempted the failing
// parse. Now they can paste it once; it persists via the existing
// setPackInstructionsUrl endpoint (no server change) so it's never
// asked again. Returns the saved URL or ''.
async function promptForInstructionsUrl_(orderNumber) {
  const row = _packQueueCache.find(r => String(r.order_number) === String(orderNumber));
  if (!row) { showToast('Order not in current list — refresh'); return ''; }
  const existing = row.instructions_pdf_url || '';
  const entered = window.prompt(
    'Instructions link for order ' + orderNumber + '\n\n'
    + 'Paste the build/assembly instructions URL (Drive or PDF link).\n'
    + 'It will be remembered for this order — you won\'t be asked again.',
    existing);
  if (entered === null) return existing; // cancelled
  const url = String(entered).trim();
  if (url && url === existing) return existing; // unchanged
  if (url && !/^https?:\/\//i.test(url)) {
    showToast('That doesn\'t look like a URL (needs http/https) — not saved');
    return existing;
  }
  if (!url) { showToast('No URL entered — nothing changed'); return existing; }
  try {
    showPackBanner_('Saving instructions link for ' + orderNumber + '…', '#42a5f5');
    const res = await groundApi('setPackInstructionsUrl', { orderNumber: orderNumber, url: url });
    if (res && res.ok) {
      row.instructions_pdf_url = url;
      try { paintPackQueue_(_packQueueCache, false); } catch (e) {}
      if (typeof openPackDetail === 'function' && _packDetailOrderNumber === orderNumber) {
        try { openPackDetail(orderNumber); } catch (e) {}
      }
      showPackBanner_('✓ Instructions link saved & remembered for ' + orderNumber, '#00e676');
      return url;
    }
    showToast('Save failed: ' + ((res && res.error) || 'unknown'));
  } catch (e) {
    showToast('Save error: ' + e.message);
  }
  return existing;
}

// v10.314 — old printOneInstruction (post-extract pick-list fallback)
// removed in favour of the SKU-resolving printInstructionsLink_ above.
// The alias near line 1824 keeps any straggler callers working.

async function printTodaysInstructions() {
  const inflight = _packQueueCache.filter(r => {
    const s = String(r.status || '');
    return s === 'pending' || s === 'in_progress' || s === 'ready_for_check' || s === 'checking';
  });
  if (inflight.length === 0) {
    showToast('No orders on today\'s list to print');
    return;
  }
  if (!confirm('Print instructions for ' + inflight.length + ' order' + (inflight.length === 1 ? '' : 's') + ' to the Brother?')) return;

  // v10.314 — bulk path uses the same SKU→InstructionsMap resolution
  // as the per-order Print button. For each order: parse INST-* SKUs
  // from sku_lines_json, bulk-resolve, print each hit as its own
  // PrintNode job (so multi-bed orders stack per-bed at the printer).
  const sorted = inflight.slice().sort((a, b) => String(a.ship_date || '').localeCompare(String(b.ship_date || '')));

  // Build the full SKU list across every order, then a single bulk
  // resolveInstructionsForSkus call (one round-trip vs N).
  const allSkus = new Set();
  const skusByOrder = {};
  for (const r of sorted) {
    let arr = [];
    try {
      const parsed = JSON.parse(String(r.sku_lines_json || '[]'));
      if (Array.isArray(parsed)) arr = parsed;
    } catch (e) { /* swallow */ }
    const inst = Array.from(new Set(arr
      .map(it => String((it && it.sku) || '').trim().toUpperCase())
      .filter(s => /^INST-/.test(s))));
    skusByOrder[r.order_number] = inst;
    inst.forEach(s => allSkus.add(s));
  }

  let mapByKey = {};
  if (allSkus.size) {
    showPackBanner_('Resolving ' + allSkus.size + ' instructions SKUs…', '#42a5f5');
    try {
      const res = await groundApi('resolveInstructionsForSkus', { skus: Array.from(allSkus) });
      if (res && res.ok && Array.isArray(res.hits)) {
        res.hits.forEach(h => { mapByKey[String(h.sku || '').toUpperCase()] = h; });
      }
    } catch (e) {
      showPackBanner_('Lookup failed: ' + e.message, '#ff5252');
      return;
    }
  }

  showPackBanner_('Stamping covers + printing ' + sorted.length + ' order' + (sorted.length === 1 ? '' : 's') + '…', '#42a5f5');
  let ok = 0, failed = [], skipped = [];
  for (let i = 0; i < sorted.length; i++) {
    const row = sorted[i];
    const instSkus = skusByOrder[row.order_number] || [];
    const hits = instSkus.map(s => mapByKey[s]).filter(Boolean);
    const misses = instSkus.filter(s => !mapByKey[s]);
    if (!hits.length) {
      skipped.push(row.order_number + (misses.length ? ' (no map entry for ' + misses.join(', ') + ')' : ' (no INST-* SKUs)'));
      continue;
    }
    for (const hit of hits) {
      showPackBanner_('Stamping ' + (i + 1) + '/' + sorted.length + ' #' + row.order_number + ' — ' + hit.sku + '…', '#42a5f5');
      try {
        const res = await stampAndPrintPackInstructions_(row, hit.pdf_url, hit.sku);
        if (res && res.ok) {
          row.instructions_printed_at = new Date().toISOString();
          ok++;
        } else {
          failed.push(row.order_number + ' ' + hit.sku + ': ' + ((res && res.error) || 'unknown'));
        }
      } catch (err) {
        failed.push(row.order_number + ' ' + hit.sku + ': ' + err.message);
      }
    }
  }
  paintPackQueue_(_packQueueCache, false); // refresh badges

  const parts = [];
  if (ok) parts.push(ok + ' packet' + (ok === 1 ? '' : 's') + ' sent');
  if (failed.length) parts.push(failed.length + ' failed');
  if (skipped.length) parts.push(skipped.length + ' skipped');
  const summary = parts.join(' · ') || 'Nothing to print';
  if (!failed.length && !skipped.length) {
    showPackBanner_('✓ ' + summary + ' 🖨', '#00e676');
  } else {
    showPackBanner_(summary, '#ff9800');
    const lines = [];
    if (skipped.length) lines.push('Skipped (no InstructionsMap entry — open More → 📑 Instructions Map):\n' + skipped.join('\n'));
    if (failed.length) lines.push('Failed:\n' + failed.join('\n'));
    alert("Print Today's Instructions — " + summary + '\n\n' + lines.join('\n\n'));
  }
}

async function printTodaysInstructionsAirPrintFallback_(inflight) {
  const withInstructions = inflight.filter(r => r.instructions_pdf_url);
  const fallbackPick = inflight.filter(r => !r.instructions_pdf_url && r.pick_list_pdf_url);
  if (!withInstructions.length && !fallbackPick.length) {
    showPackBanner_('No PDFs available to print', '#ff5252');
    return;
  }
  const total = withInstructions.length + fallbackPick.length;
  showPackBanner_('Merging ' + total + ' PDFs for AirPrint…', '#42a5f5');
  try {
    const PDFLib = await loadPdfLib_();
    const merged = await PDFLib.PDFDocument.create();
    const all = withInstructions.concat(fallbackPick);
    let done = 0, failed = [];
    for (const r of all) {
      const url = r.instructions_pdf_url || r.pick_list_pdf_url;
      try {
        const bytes = await packFetchPdfBytes_(url);
        const src = await PDFLib.PDFDocument.load(bytes, { ignoreEncryption: true });
        const pages = await merged.copyPages(src, src.getPageIndices());
        pages.forEach(p => merged.addPage(p));
        done++;
      } catch (err) {
        failed.push(r.order_number + ': ' + err.message);
      }
    }
    if (!done) {
      showPackBanner_('AirPrint merge failed — see alert', '#ff5252');
      alert('Could not merge any PDFs:\n\n' + failed.join('\n'));
      return;
    }
    const mergedBytes = await merged.save();
    const blob = new Blob([mergedBytes], { type: 'application/pdf' });
    const blobUrl = URL.createObjectURL(blob);
    const w = window.open(blobUrl, '_blank');
    if (!w) { showPackBanner_('Allow popups, then retry', '#ff9800'); return; }
    setTimeout(() => URL.revokeObjectURL(blobUrl), 5 * 60 * 1000);
    showPackBanner_(done + ' merged · Share → Print → AirPrint', '#00e676');
  } catch (err) {
    showPackBanner_('AirPrint fallback error: ' + err.message, '#ff5252');
  }
}

async function bulkRemoveFromList() {
  if (!_packBulkSelection.size) {
    showToast('Select at least one order first');
    return;
  }
  const orderNumbers = Array.from(_packBulkSelection);
  if (!confirm('Remove ' + orderNumbers.length + ' order' + (orderNumbers.length === 1 ? '' : 's') + ' from today\'s list?\n\n(Status unchanged — they can be re-added with + Add Order #.)')) return;
  const pin = promptManagerPin_('remove ' + orderNumbers.length + ' from list');
  if (!pin) return;
  try {
    const res = await groundApi('removeFromTodaysPackList', {
      orderNumbers: orderNumbers,
      manager_pin: pin,
    });
    if (!res || !res.ok) {
      if (res && /pin/i.test(res.error || '')) clearManagerPin_();
      showToast(((res && res.error) || 'Remove failed'));
      return;
    }
    _packBulkSelection.clear();
    await refreshPackQueue();
    showPackBanner_(res.removed + ' order' + (res.removed === 1 ? '' : 's') + ' removed from list 🗑', '#42a5f5');
  } catch (err) {
    showToast('Remove error: ' + err.message);
  }
}

async function resetTodaysPackList() {
  // v10.542 — Zac: clicked Clear List from Orders tab, got "list is
  // already empty" while 4 orders were visibly on Pack Today. Root
  // cause: _packQueueCache (legacy Pack tab cache) was empty because
  // Zac hadn't opened that tab; the Orders tab uses _orderPipelineCache.
  // Fall back to the pipeline cache, then trust the server count.
  let inflight = 0;
  if (Array.isArray(_packQueueCache) && _packQueueCache.length) {
    inflight = _packQueueCache.filter(r => {
      const s = String(r.status || '');
      return s === 'pending' || s === 'in_progress' || s === 'ready_for_check' || s === 'checking';
    }).length;
  }
  if (!inflight && Array.isArray(_orderPipelineCache)) {
    inflight = _orderPipelineCache.filter(o => o && o.is_on_active_list).length;
  }
  if (!confirm('Reset the entire pack list?\n\n' + (inflight ? ('All ' + inflight + ' in-flight order' + (inflight === 1 ? '' : 's') + ' will be removed from the list.') : 'Every order with on_active_list=TRUE will be flipped to FALSE (the client cache may be stale — let the server tell us the true count).') + ' Status is unchanged — they can be re-added.\n\nPacked orders awaiting ship are NOT affected.')) return;
  const pin = promptManagerPin_('reset entire list');
  if (!pin) return;
  try {
    const res = await groundApi('clearTodaysPackList', { manager_pin: pin });
    if (!res || !res.ok) {
      if (res && /pin/i.test(res.error || '')) clearManagerPin_();
      showToast(((res && res.error) || 'Reset failed'));
      return;
    }
    _packBulkSelection.clear();
    await refreshPackQueue();
    // v10.543 — when reset is invoked from the Orders tab, also force
    // a pipeline refresh so the Pack lens reflects the cleared state.
    // The old code only refreshed _packQueueCache (the Pack tab's
    // cache); _orderPipelineCache was stale → the Orders tab kept
    // showing the same orders even after a successful server-side clear.
    try {
      if (typeof refreshOrderPipeline === 'function') {
        await refreshOrderPipeline({ force: true });
        if (typeof renderOrdersTab === 'function') renderOrdersTab();
      }
    } catch (e) { /* swallow */ }
    const msg = 'List reset — ' + res.cleared + ' order' + (res.cleared === 1 ? '' : 's') + ' cleared ↺';
    if (typeof showPackBanner_ === 'function') showPackBanner_(msg, '#42a5f5');
    else showToast(msg);
  } catch (err) {
    showToast('Reset error: ' + err.message);
  }
}

async function addOrderByNumberPrompt() {
  const input = prompt('Order number to add to today\'s list?\n\n(If the order isn\'t in PackingQueue yet, the orchestrator will look it up in the MBD:FL SHIPMENTS calendar and bootstrap a row.)');
  if (input == null) return;
  const orderNumber = String(input).trim().replace(/^#/, '');
  if (!orderNumber || !/^\d+$/.test(orderNumber)) { showToast('Enter a numeric order number'); return; }
  const pin = promptManagerPin_('add order ' + orderNumber);
  if (!pin) return;
  showPackBanner_('Adding order ' + orderNumber + '…', '#42a5f5');
  try {
    const res = await groundApi('addOrderByNumber', { orderNumber: orderNumber, manager_pin: pin });
    if (!res || !res.ok) {
      if (res && /pin/i.test(res.error || '')) clearManagerPin_();
      showPackBanner_((res && res.error) || 'Add failed', '#ff5252');
      return;
    }
    await refreshPackQueue();
    if (res.source === 'existing_row') {
      showPackBanner_('Order ' + orderNumber + ' added to list ✓', '#00e676');
    } else if (res.source === 'calendar') {
      const note = res.pickListUrl
        ? 'Bootstrapped from calendar. Open it to auto-parse the pick list and pull SKUs.'
        : 'Bootstrapped from calendar but no pick-list URL found in the event. You may need to upload the PDF manually.';
      showPackBanner_('Order ' + orderNumber + ' added (from calendar) — ' + note, '#00e676');
    } else {
      showPackBanner_('Order ' + orderNumber + ' added', '#00e676');
    }
  } catch (err) {
    showPackBanner_('Add error: ' + err.message, '#ff5252');
  }
}

async function batchAddOrdersPrompt() {
  const input = prompt('Paste order numbers to add to today\'s list.\n\nSeparate with commas, spaces, or new lines.\n\n(Rows not yet in PackingQueue will be bootstrapped from the MBD:FL SHIPMENTS calendar. One PIN entry covers the whole batch.)');
  if (input == null) return;
  const orderNumbers = String(input)
    .split(/[\s,;]+/)
    .map(s => s.trim().replace(/^#/, ''))
    .filter(s => s.length && /^\d+$/.test(s));
  if (!orderNumbers.length) { showToast('No numeric order numbers found'); return; }
  // De-dupe while preserving order.
  const seen = new Set();
  const deduped = orderNumbers.filter(n => { if (seen.has(n)) return false; seen.add(n); return true; });
  if (!confirm('Add ' + deduped.length + ' order' + (deduped.length === 1 ? '' : 's') + ' to today\'s list?\n\n' + deduped.join(', '))) return;
  const pin = promptManagerPin_('batch add ' + deduped.length + ' orders');
  if (!pin) return;
  // v10.547 — Zac (post v10.546): "added 8 orders, looked like it
  // failed, then several minutes later they appeared, no loading
  // indication, wow slow." Cause: addOrdersByNumber loops per-order
  // and each gcal-bootstrap is a separate listScheduleByDateRange
  // round-trip; 8 orders × few seconds = 30-120s. The Orders-tab
  // onclick fired a 1.2s-setTimeout refreshOrderPipeline that ran
  // BEFORE the server returned. Fixes:
  //   1. Persistent global loader during the await (doesn't auto-
  //      hide on 6s like showPackBanner_) so the user knows it's
  //      still working.
  //   2. Trigger the Orders pipeline refresh AFTER server returns,
  //      not on a hardcoded timeout from the click handler.
  const elapsedTick = (() => {
    const start = Date.now();
    const loader = (typeof showGlobalLoader === 'function')
      ? showGlobalLoader('Adding ' + deduped.length + ' order' + (deduped.length === 1 ? '' : 's') + '… (gcal lookups can take 5–15s each)')
      : null;
    let tickId = null;
    if (loader && loader.setText) {
      tickId = setInterval(() => {
        const s = Math.round((Date.now() - start) / 1000);
        loader.setText('Adding ' + deduped.length + ' order' + (deduped.length === 1 ? '' : 's')
          + '… ' + s + 's elapsed (gcal bootstrap, hang on)');
      }, 1000);
    }
    return { stop: () => { if (tickId) clearInterval(tickId); if (loader && loader.stop) loader.stop(); } };
  })();
  showPackBanner_('Adding ' + deduped.length + ' order' + (deduped.length === 1 ? '' : 's') + '…', '#42a5f5');
  try {
    const res = await groundApi('addOrdersByNumber', { orderNumbers: deduped, manager_pin: pin });
    if (!res || !res.ok) {
      elapsedTick.stop();
      if (res && /pin/i.test(res.error || '')) clearManagerPin_();
      showPackBanner_((res && res.error) || 'Batch add failed', '#ff5252');
      showToast((res && res.error) || 'Batch add failed');
      return;
    }
    // Refresh both caches so whichever tab Zac is on reflects the new
    // list state immediately.
    await refreshPackQueue();
    if (typeof refreshOrderPipeline === 'function') {
      try { await refreshOrderPipeline({ force: true }); } catch (e) {}
      if (typeof renderOrdersTab === 'function') { try { renderOrdersTab(); } catch (e) {} }
    }
    elapsedTick.stop();
    if (res.failed === 0) {
      showPackBanner_('+ ' + res.added + ' added to list ✓', '#00e676');
      showToast('+ ' + res.added + ' added to today’s list');
    } else {
      const fails = (res.results || []).filter(r => !r.ok).map(r => r.orderNumber + ' (' + r.error + ')').join('; ');
      showPackBanner_(res.added + ' added · ' + res.failed + ' failed: ' + fails, '#ff9800');
      showToast(res.added + ' added · ' + res.failed + ' failed');
    }
  } catch (err) {
    elapsedTick.stop();
    showPackBanner_('Batch add error: ' + err.message, '#ff5252');
    showToast('Batch add error: ' + err.message);
  }
}

async function addToTodaysListPrompt() {
  const inflightNow = _packQueueCache.filter(r => {
    const s = String(r.status || '');
    return s === 'pending' || s === 'in_progress' || s === 'ready_for_check' || s === 'checking';
  }).length;
  const suggested = Math.max(1, 12 - inflightNow);
  const input = prompt('How many orders to add to today\'s list?', String(suggested));
  if (input == null) return;
  const count = parseInt(input, 10);
  if (!count || count < 1) { showToast('Enter a positive number'); return; }

  const pin = promptManagerPin_('add to list');
  if (!pin) return;

  try {
    const res = await groundApi('addToTodaysPackList', { count: count, manager_pin: pin });
    if (!res || !res.ok) {
      if (res && /pin/i.test(res.error || '')) clearManagerPin_();
      showToast((res && res.error) || 'Add failed');
      return;
    }
    // v10.432 — Zac: "acted like it worked but nothing changed on the
    // list." The server-side endpoint only flips rows not already
    // explicit-TRUE — so when all in-window candidates are already
    // auto-flagged, added=0 even though the call "succeeded." Make
    // that visible.
    const added = Number(res.added || 0);
    const bootstrapped = Number(res.gcal_bootstrapped || 0);
    const total = Number(res.totalActive || 0);
    if (added > 0) {
      const extra = bootstrapped > 0 ? ' (' + bootstrapped + ' bootstrapped from gcal)' : '';
      showPackBanner_('+ ' + added + ' added' + extra + ' · ' + total + ' on today\'s list', '#42a5f5');
    } else {
      showPackBanner_('No new orders to add (all candidates already on list)', '#FFB300');
    }
    await refreshPackQueue();
    // v10.432 — also refresh the Orders-tab pipeline so the Pack Today
    // lens reflects the change immediately. v10.421's button wrap
    // delayed this by 1.2s; doing it inline is simpler + faster.
    if (typeof refreshOrderPipeline === 'function') {
      try { await refreshOrderPipeline({ force: true }); } catch (e) {}
      if (typeof renderOrdersTab === 'function') renderOrdersTab();
    }
  } catch (err) {
    showToast('Add error: ' + err.message);
  }
}

