// v10.652 (Zac 2026-06-17) — Optimistic UI. Previously every drop +
// task action did `await refreshPackPlanner_()` which fired the full
// 60s fishing-animation reload. That's why tap-and-tap felt broken
// ("nothing happens then a minute later it appears") AND why adding a
// task during a pending drop lost the task (the drop's refresh
// clobbered the in-progress add). Now: mutate the local cache + render
// instantly + fire server save in background. If save fails, rollback
// the cache to its pre-mutation state.
function _plannerSnapshotCache_() {
  if (!_packPlannerCache) return null;
  return JSON.parse(JSON.stringify(_packPlannerCache));
}
function _plannerRestoreCache_(snapshot) {
  if (snapshot) {
    _packPlannerCache = snapshot;
    _renderPackPlanner_(_packPlannerCache);
  }
}
// v10.667 — returns a per-op rollback record { moved, fromBucket }
// so concurrent drops + unschedules can each revert ONLY their own
// mutation. Returns null on cache miss.
function _plannerMoveOrderInCache_(orderNumber, targetDate, targetBucket) {
  if (!_packPlannerCache) return null;
  const cache = _packPlannerCache;
  let moving = null;
  let fromUnsched = false;
  let fromDate = null;
  let fromBucket = null;
  let fromPastDue = false;
  if (Array.isArray(cache.unscheduled)) {
    const ix = cache.unscheduled.findIndex(o => String(o.order_number) === String(orderNumber));
    if (ix >= 0) { moving = cache.unscheduled.splice(ix, 1)[0]; fromUnsched = true; }
  }
  if (!moving && cache.orders_by_date) {
    Object.keys(cache.orders_by_date).some(d => {
      return ['make', 'pack'].some(b => {
        const arr = (cache.orders_by_date[d] || {})[b] || [];
        const ix = arr.findIndex(o => String(o.order_number) === String(orderNumber));
        if (ix >= 0) {
          moving = arr.splice(ix, 1)[0];
          fromDate = d; fromBucket = b;
          return true;
        }
        return false;
      });
    });
  }
  if (!moving && Array.isArray(cache.past_due)) {
    const ix = cache.past_due.findIndex(o => String(o.order_number) === String(orderNumber));
    if (ix >= 0) { moving = cache.past_due.splice(ix, 1)[0]; fromPastDue = true; }
  }
  if (!moving) return null;
  moving.pack_bucket = targetBucket;
  cache.orders_by_date = cache.orders_by_date || {};
  cache.orders_by_date[targetDate] = cache.orders_by_date[targetDate] || { make: [], pack: [] };
  cache.orders_by_date[targetDate][targetBucket] = cache.orders_by_date[targetDate][targetBucket] || [];
  cache.orders_by_date[targetDate][targetBucket].push(moving);
  cache.unscheduled_count = (cache.unscheduled || []).length;
  cache.past_due_count = (cache.past_due || []).length;
  return {
    moved: moving,
    toDate: targetDate, toBucket: targetBucket,
    fromUnsched, fromDate, fromBucket, fromPastDue,
  };
}

// v10.667 — undo a drop using the rollback record from
// _plannerMoveOrderInCache_. Only touches the moved row; doesn't
// disturb other concurrent mutations.
function _plannerLocalRollbackDrop_(rb) {
  if (!_packPlannerCache || !rb || !rb.moved) return;
  const cache = _packPlannerCache;
  const on = String(rb.moved.order_number);
  // Remove from the destination first.
  if (cache.orders_by_date && cache.orders_by_date[rb.toDate]) {
    const arr = cache.orders_by_date[rb.toDate][rb.toBucket] || [];
    const ix = arr.findIndex(o => String(o.order_number) === on);
    if (ix >= 0) arr.splice(ix, 1);
  }
  // Put back where it came from.
  if (rb.fromUnsched) {
    cache.unscheduled = cache.unscheduled || [];
    cache.unscheduled.push(rb.moved);
  } else if (rb.fromPastDue) {
    cache.past_due = cache.past_due || [];
    cache.past_due.push(rb.moved);
  } else if (rb.fromDate && rb.fromBucket) {
    cache.orders_by_date = cache.orders_by_date || {};
    cache.orders_by_date[rb.fromDate] = cache.orders_by_date[rb.fromDate] || { make: [], pack: [] };
    cache.orders_by_date[rb.fromDate][rb.fromBucket] = cache.orders_by_date[rb.fromDate][rb.fromBucket] || [];
    cache.orders_by_date[rb.fromDate][rb.fromBucket].push(rb.moved);
  }
  cache.unscheduled_count = (cache.unscheduled || []).length;
  cache.past_due_count = (cache.past_due || []).length;
  _renderPackPlanner_(cache);
}

// v10.662 (Zac 2026-06-17) — unschedule a day-bucket order back into
// the "To Be Scheduled" sidebar. Optimistic: splice locally + re-render,
// then setPackTargetDate('') server-side. On failure, roll back.
// v10.671 — Mark a past-due cabinet order as shipped from the planner.
// Optimistic: splice from past_due locally, then call server endpoint
// markPackJobShipped. Same per-op rollback pattern as v10.667.
async function _plannerMarkShipped_(orderNumber) {
  showToast('Marking ' + orderNumber + ' shipped…');
  const pin = getCachedManagerPin_() || promptManagerPin_('mark shipped');
  if (!pin) return;
  if (!_scheduleLock_(orderNumber)) {
    showToast('Already moving #' + orderNumber + '…');
    return;
  }
  let removed = null;
  if (_packPlannerCache && Array.isArray(_packPlannerCache.past_due)) {
    const ix = _packPlannerCache.past_due.findIndex(o => String(o.order_number) === String(orderNumber));
    if (ix >= 0) {
      removed = _packPlannerCache.past_due.splice(ix, 1)[0];
      _packPlannerCache.past_due_count = _packPlannerCache.past_due.length;
      _renderPackPlanner_(_packPlannerCache);
      showToast('✓ ' + orderNumber + ' marked shipped');
    }
  }
  try {
    const r = await groundApi('markPackJobShipped', {
      orderNumber, manager_pin: pin,
    });
    if (r && !r.ok) {
      // Roll back: re-insert + re-render.
      if (removed && _packPlannerCache) {
        _packPlannerCache.past_due = _packPlannerCache.past_due || [];
        _packPlannerCache.past_due.push(removed);
        _packPlannerCache.past_due_count = _packPlannerCache.past_due.length;
        _renderPackPlanner_(_packPlannerCache);
      }
      _handleApiErrorWithPin_(r, 'Mark shipped failed (rolled back)');
    }
  } catch (e) {
    if (removed && _packPlannerCache) {
      _packPlannerCache.past_due = _packPlannerCache.past_due || [];
      _packPlannerCache.past_due.push(removed);
      _packPlannerCache.past_due_count = _packPlannerCache.past_due.length;
      _renderPackPlanner_(_packPlannerCache);
    }
    showToast('Network error (rolled back): ' + e.message);
  } finally {
    _scheduleUnlock_(orderNumber);
  }
}

async function _plannerUnschedule_(orderNumber) {
  showToast('Moving ' + orderNumber + ' back…');
  console.log('DIAG-V10.667-UNSCHED tap', orderNumber);
  const pin = getCachedManagerPin_() || promptManagerPin_('unschedule');
  if (!pin) return;
  if (!_scheduleLock_(orderNumber)) {
    showToast('Already moving #' + orderNumber + '…');
    return;
  }
  // v10.667 — per-op rollback record instead of global snapshot. Two
  // simultaneous unschedules each remember only what THEY moved, so
  // one's rollback can't clobber the other's optimistic mutation.
  let rollback = null;
  if (_packPlannerCache) {
    const cache = _packPlannerCache;
    let moved = null;
    let fromDate = null;
    let fromBucket = null;
    let fromPastDue = false;
    if (cache.orders_by_date) {
      Object.keys(cache.orders_by_date).some(d => {
        return ['make', 'pack'].some(b => {
          const arr = (cache.orders_by_date[d] || {})[b] || [];
          const ix = arr.findIndex(o => String(o.order_number) === String(orderNumber));
          if (ix >= 0) {
            moved = arr.splice(ix, 1)[0];
            fromDate = d; fromBucket = b;
            return true;
          }
          return false;
        });
      });
    }
    if (!moved && Array.isArray(cache.past_due)) {
      const ix = cache.past_due.findIndex(o => String(o.order_number) === String(orderNumber));
      if (ix >= 0) {
        moved = cache.past_due.splice(ix, 1)[0];
        fromPastDue = true;
      }
    }
    if (moved) {
      cache.unscheduled = cache.unscheduled || [];
      cache.unscheduled.push(moved);
      cache.unscheduled_count = cache.unscheduled.length;
      _renderPackPlanner_(cache);
      showToast('↩ ' + orderNumber + ' → To Be Scheduled');
      rollback = { moved, fromDate, fromBucket, fromPastDue };
    } else {
      console.log('DIAG-V10.667-UNSCHED order not found in cache', orderNumber);
      showToast('Could not find ' + orderNumber + ' — try refresh');
    }
  } else {
    showToast('Planner cache empty — try refresh');
  }
  try {
    const r = await groundApi('setPackTargetDate', {
      orderNumber, targetDate: '', manager_pin: pin,
      set_by: localStorage.getItem('mbd_ground_packer') || '',
    });
    if (r && !r.ok) {
      if (rollback) _plannerLocalRollback_(rollback);
      _handleApiErrorWithPin_(r, 'Unschedule failed (rolled back)');
    }
  } catch (e) {
    if (rollback) _plannerLocalRollback_(rollback);
    showToast('Network error (rolled back): ' + e.message);
  } finally {
    _scheduleUnlock_(orderNumber);
  }
}

// v10.667 — per-op rollback. Removes the order from unscheduled +
// re-inserts where it came from. Touches ONLY the moved row; other
// concurrent ops' mutations stay intact.
function _plannerLocalRollback_(rb) {
  if (!_packPlannerCache || !rb || !rb.moved) return;
  const cache = _packPlannerCache;
  const on = String(rb.moved.order_number);
  if (Array.isArray(cache.unscheduled)) {
    const ix = cache.unscheduled.findIndex(o => String(o.order_number) === on);
    if (ix >= 0) cache.unscheduled.splice(ix, 1);
    cache.unscheduled_count = cache.unscheduled.length;
  }
  if (rb.fromPastDue) {
    cache.past_due = cache.past_due || [];
    cache.past_due.push(rb.moved);
  } else if (rb.fromDate && rb.fromBucket) {
    cache.orders_by_date = cache.orders_by_date || {};
    cache.orders_by_date[rb.fromDate] = cache.orders_by_date[rb.fromDate] || { make: [], pack: [] };
    cache.orders_by_date[rb.fromDate][rb.fromBucket] = cache.orders_by_date[rb.fromDate][rb.fromBucket] || [];
    cache.orders_by_date[rb.fromDate][rb.fromBucket].push(rb.moved);
  }
  _renderPackPlanner_(cache);
}

async function _plannerDropOnDay_(targetDate, targetBucket) {
  if (!_packPlannerSelectedOrder) {
    showToast('Tap an order in the sidebar first');
    return;
  }
  const pin = getCachedManagerPin_() || promptManagerPin_('drop on day');
  if (!pin) return;
  const orderNumber = _packPlannerSelectedOrder.order_number;
  // v10.628 — debounce double-taps.
  if (!_scheduleLock_(orderNumber)) {
    showToast('Already moving #' + orderNumber + '…');
    return;
  }
  // v10.667 — per-op rollback (record of THIS op's mutation only) so
  // concurrent drops/unschedules don't clobber each other.
  const rollback = _plannerMoveOrderInCache_(orderNumber, targetDate, targetBucket);
  _packPlannerSelectedOrder = null;
  // v10.687 — clear mobile selected-banner now that drop is in flight.
  if (typeof _plannerHideMobileSelectedBanner_ === 'function') _plannerHideMobileSelectedBanner_();
  if (rollback) {
    _renderPackPlanner_(_packPlannerCache);
    showToast('✓ #' + orderNumber + ' → ' + targetDate + ' (' + targetBucket + ')');
  }
  try {
    const r1 = await groundApi('setPackTargetDate', {
      orderNumber, targetDate, manager_pin: pin, set_by: localStorage.getItem('mbd_ground_packer') || ''
    });
    if (r1 && !r1.ok) {
      if (rollback) _plannerLocalRollbackDrop_(rollback);
      _handleApiErrorWithPin_(r1, 'Drop failed (rolled back)');
      return;
    }
    const r2 = await groundApi('setOrderPackBucket', {
      order_number: orderNumber, bucket: targetBucket, manager_pin: pin
    });
    if (r2 && !r2.ok) {
      // Server's pack_target_date IS set; only the bucket failed. Don't
      // roll back the whole optimistic move — toast the partial failure
      // so the user knows the bucket label may not survive a refresh.
      showToast('Bucket save failed (date saved): ' + (r2.error || 'unknown'));
    }
  } catch (e) {
    if (rollback) _plannerLocalRollbackDrop_(rollback);
    showToast('Network error (rolled back): ' + e.message);
  } finally {
    _scheduleUnlock_(orderNumber);
  }
}

async function _plannerAddTask_(targetDate) {
  const title = prompt('Task title (for ' + targetDate + '):');
  if (!title || !title.trim()) return;
  const assignee = prompt('Assignee (optional — Jonah, Shane, etc.):') || '';
  const priority = prompt('Priority? low / normal / high (default normal):') || 'normal';
  // v10.652 — optimistic add. Append a temp task to the cache
  // immediately; replace the temp id with the real one after server
  // returns. If server fails, remove the temp task + toast.
  const tempId = 'tmp_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8);
  const tempTask = {
    task_id: tempId,
    title: title.trim(),
    assignee: assignee.trim(),
    priority: priority.trim().toLowerCase() || 'normal',
    target_date: targetDate,
    status: 'pending',
    _pending: true,
  };
  if (_packPlannerCache) {
    _packPlannerCache.tasks_by_date = _packPlannerCache.tasks_by_date || {};
    _packPlannerCache.tasks_by_date[targetDate] = _packPlannerCache.tasks_by_date[targetDate] || [];
    _packPlannerCache.tasks_by_date[targetDate].push(tempTask);
    _renderPackPlanner_(_packPlannerCache);
  }
  return _plannerAuthedCall_('add task', async (pin) => {
    const res = await groundApi('addPackTask', {
      title: tempTask.title,
      assignee: tempTask.assignee,
      priority: tempTask.priority,
      target_date: targetDate,
      created_by: localStorage.getItem('mbd_ground_packer') || '',
      manager_pin: pin,
    });
    if (_handleApiErrorWithPin_(res, 'Add task failed')) {
      // Roll the temp out.
      if (_packPlannerCache && _packPlannerCache.tasks_by_date) {
        const arr = _packPlannerCache.tasks_by_date[targetDate] || [];
        const ix = arr.findIndex(t => t.task_id === tempId);
        if (ix >= 0) arr.splice(ix, 1);
        _renderPackPlanner_(_packPlannerCache);
      }
      return;
    }
    // Swap temp id for real id so subsequent toggle/delete works.
    if (res && res.task_id && _packPlannerCache && _packPlannerCache.tasks_by_date) {
      const arr = _packPlannerCache.tasks_by_date[targetDate] || [];
      const t = arr.find(x => x.task_id === tempId);
      if (t) { t.task_id = res.task_id; t._pending = false; }
      _renderPackPlanner_(_packPlannerCache);
    }
    showToast('✓ Task added');
  });
}

async function _plannerToggleTask_(taskId, newStatus) {
  // v10.652 — optimistic toggle. Find the task in cache, flip status,
  // re-render; revert if server save fails.
  let prevStatus = null;
  let owner = null;
  if (_packPlannerCache && _packPlannerCache.tasks_by_date) {
    Object.keys(_packPlannerCache.tasks_by_date).forEach(d => {
      const arr = _packPlannerCache.tasks_by_date[d] || [];
      const t = arr.find(x => x.task_id === taskId);
      if (t && !owner) { owner = t; prevStatus = t.status; t.status = newStatus; }
    });
    if (owner) _renderPackPlanner_(_packPlannerCache);
  }
  return _plannerAuthedCall_('toggle task', async (pin) => {
    const res = await groundApi('updatePackTask', {
      task_id: taskId, status: newStatus, manager_pin: pin,
      completed_by: localStorage.getItem('mbd_ground_packer') || '',
    });
    if (_handleApiErrorWithPin_(res, 'Update failed')) {
      if (owner) { owner.status = prevStatus; _renderPackPlanner_(_packPlannerCache); }
      return;
    }
  });
}

async function _plannerDeleteTask_(taskId) {
  if (!confirm('Delete this task?')) return;
  // v10.652 — optimistic delete. Remove from cache, re-render. If
  // server fails, restore from a saved copy.
  let removedTask = null;
  let removedFromDate = null;
  if (_packPlannerCache && _packPlannerCache.tasks_by_date) {
    Object.keys(_packPlannerCache.tasks_by_date).forEach(d => {
      const arr = _packPlannerCache.tasks_by_date[d] || [];
      const ix = arr.findIndex(t => t.task_id === taskId);
      if (ix >= 0 && !removedTask) {
        removedTask = arr.splice(ix, 1)[0];
        removedFromDate = d;
      }
    });
    if (removedTask) _renderPackPlanner_(_packPlannerCache);
  }
  return _plannerAuthedCall_('delete task', async (pin) => {
    const res = await groundApi('deletePackTask', { task_id: taskId, manager_pin: pin });
    if (_handleApiErrorWithPin_(res, 'Delete failed')) {
      if (removedTask && removedFromDate && _packPlannerCache) {
        _packPlannerCache.tasks_by_date[removedFromDate] = _packPlannerCache.tasks_by_date[removedFromDate] || [];
        _packPlannerCache.tasks_by_date[removedFromDate].push(removedTask);
        _renderPackPlanner_(_packPlannerCache);
      }
      return;
    }
    showToast('✓ Task deleted');
  });
}

// v10.606 (Zac 2026-06-16) — Interactive survey overlay. Lets
// stakeholders (Seth, Norm, etc.) answer design questions inside
// the PWA via tap-through choices + optional notes. Submit hits
// submitSurvey → saves to Murphy Ops `Surveys` tab + Slack-pings
// Zac. Deep-linkable via ?survey=<surveyId> on the PWA URL.
async function openSethSurvey(surveyId) {
  surveyId = String(surveyId || '').trim();
  if (!surveyId) return;
  const prior = document.getElementById('sethSurveyOverlay');
  if (prior) prior.remove();
  const ov = document.createElement('div');
  ov.id = 'sethSurveyOverlay';
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.88);z-index:10006;display:flex;align-items:flex-start;justify-content:center;padding:18px;overflow-y:auto';
  ov.innerHTML = '<div class="no-dark keep-dark-text" onclick="event.stopPropagation()" id="sethSurveyCard" style="background:#fff !important;color:#1a1a1a !important;-webkit-text-fill-color:#1a1a1a !important;border-radius:14px;padding:24px;max-width:640px;width:100%;margin-top:20px;margin-bottom:40px">'
    + '<div style="text-align:center;padding:30px;color:#666 !important;-webkit-text-fill-color:#666 !important">⟳ Loading survey…</div>'
    + '</div>';
  ov.onclick = (e) => { if (e.target === ov) ov.remove(); };
  document.body.appendChild(ov);
  let data;
  try {
    data = await groundApi('getSurvey', { surveyId });
  } catch (e) {
    document.getElementById('sethSurveyCard').innerHTML = '<div style="color:#c62828 !important;-webkit-text-fill-color:#c62828 !important;padding:20px">Network error: ' + esc(e.message) + '</div>';
    return;
  }
  if (!data || !data.ok) {
    document.getElementById('sethSurveyCard').innerHTML = '<div style="color:#c62828 !important;-webkit-text-fill-color:#c62828 !important;padding:20px">' + esc((data && data.error) || 'unknown error') + '</div>';
    return;
  }
  _renderSethSurvey_(data.survey, data.prior_submissions_count || 0);
}

function _renderSethSurvey_(survey, priorCount) {
  const card = document.getElementById('sethSurveyCard');
  if (!card) return;
  const labelStyle = 'display:block;font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:.5px;color:#5B21B6 !important;-webkit-text-fill-color:#5B21B6 !important;margin-bottom:6px;margin-top:18px';
  const inputStyle = 'width:100%;padding:10px 12px;background:#fff !important;color:#1a1a1a !important;-webkit-text-fill-color:#1a1a1a !important;border:1.5px solid #ccc;border-radius:8px;font-size:14px;font-family:inherit;box-sizing:border-box';

  let html = ''
    + '<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin-bottom:8px">'
    +   '<div style="font-family:\'Barlow Condensed\',Arial,sans-serif;font-size:26px;font-weight:900;color:#1a1a1a !important;-webkit-text-fill-color:#1a1a1a !important;letter-spacing:.5px;line-height:1.05">' + esc(survey.title) + '</div>'
    +   '<button onclick="document.getElementById(\'sethSurveyOverlay\').remove()" style="padding:8px 12px;background:#1a1a1a !important;color:#fff !important;-webkit-text-fill-color:#fff !important;border:none;border-radius:8px;font-size:13px;font-weight:700;cursor:pointer">✕</button>'
    + '</div>'
    + (priorCount > 0 ? '<div style="font-size:11px;color:#888 !important;-webkit-text-fill-color:#888 !important;margin-bottom:8px">' + priorCount + ' prior submission' + (priorCount === 1 ? '' : 's') + ' on file</div>' : '')
    + (survey.intro ? '<div style="font-size:13px;color:#444 !important;-webkit-text-fill-color:#444 !important;line-height:1.5;background:#fafafa !important;padding:14px;border-radius:8px;border-left:4px solid #7C3AED">' + esc(survey.intro) + '</div>' : '')
    + '<label style="' + labelStyle + '">Your name</label>'
    + '<input id="sethSurveyRespondent" type="text" placeholder="e.g. Seth Davis" style="' + inputStyle + '">';

  survey.questions.forEach((q, qi) => {
    html += '<div style="margin-top:22px;padding-top:18px;border-top:1px solid #eee">';
    html += '<div style="font-size:15px;font-weight:800;color:#1a1a1a !important;-webkit-text-fill-color:#1a1a1a !important;line-height:1.35;margin-bottom:8px">' + (qi + 1) + '. ' + esc(q.text) + (q.optional ? ' <span style="font-size:11px;color:#888 !important;-webkit-text-fill-color:#888 !important;font-weight:600">(optional)</span>' : '') + '</div>';
    if (q.help) {
      html += '<div style="font-size:11px;color:#666 !important;-webkit-text-fill-color:#666 !important;font-style:italic;margin-bottom:10px">' + esc(q.help) + '</div>';
    }
    if (q.type === 'choice') {
      (q.options || []).forEach((opt, oi) => {
        const inputId = 'ssq_' + q.id + '_' + oi;
        html += '<label for="' + inputId + '" style="display:flex;align-items:flex-start;gap:10px;padding:11px 13px;margin-bottom:6px;background:#f5f5f5 !important;border:1.5px solid #ddd;border-radius:8px;cursor:pointer;font-size:13px;color:#1a1a1a !important;-webkit-text-fill-color:#1a1a1a !important;line-height:1.4">'
          + '<input type="radio" id="' + inputId + '" name="ssq_' + q.id + '" value="' + esc(opt.value) + '" style="margin-top:3px;flex-shrink:0;width:18px;height:18px;cursor:pointer">'
          + '<span>' + esc(opt.label) + '</span>'
          + '</label>';
      });
    } else if (q.type === 'text') {
      html += '<textarea id="ssq_' + q.id + '" rows="3" placeholder="' + esc(q.placeholder || '') + '" style="' + inputStyle + ';font-family:inherit;resize:vertical"></textarea>';
    }
    html += '</div>';
  });

  html += ''
    + '<div style="margin-top:24px;padding-top:18px;border-top:2px solid #7C3AED;display:flex;gap:8px">'
    +   '<button onclick="_submitSethSurvey_(\'' + esc(survey.id) + '\')" class="ss-submit-btn" style="flex:1;padding:16px;background:linear-gradient(180deg,#7C3AED 0%,#4C1D95 100%) !important;color:#fff !important;-webkit-text-fill-color:#fff !important;border:none;border-radius:10px;font-size:15px;font-weight:900;letter-spacing:.5px;cursor:pointer">✓ Submit Answers</button>'
    +   '<button onclick="document.getElementById(\'sethSurveyOverlay\').remove()" style="padding:16px 22px;background:#1a1a1a !important;color:#fff !important;-webkit-text-fill-color:#fff !important;border:none;border-radius:10px;font-size:14px;font-weight:700;cursor:pointer">Close</button>'
    + '</div>';

  card.innerHTML = html;
}

async function _submitSethSurvey_(surveyId) {
  const card = document.getElementById('sethSurveyCard');
  if (!card) return;
  const respondent = (document.getElementById('sethSurveyRespondent').value || '').trim();
  const btn = document.querySelector('.ss-submit-btn');
  // Gather answers.
  const answers = {};
  // Choice questions: find checked radio per question.
  const radios = card.querySelectorAll('input[type="radio"]:checked');
  radios.forEach(r => {
    const qid = r.name.replace(/^ssq_/, '');
    answers[qid] = r.value;
  });
  // Text questions.
  const textAreas = card.querySelectorAll('textarea[id^="ssq_"]');
  textAreas.forEach(t => {
    const qid = t.id.replace(/^ssq_/, '');
    const val = (t.value || '').trim();
    if (val) answers[qid] = val;
  });
  if (!respondent) {
    showToast('Add your name before submitting');
    return;
  }
  if (Object.keys(answers).length === 0) {
    showToast('Answer at least one question first');
    return;
  }
  if (btn) { btn.disabled = true; btn.innerHTML = '⏳ Submitting…'; btn.style.opacity = '.7'; }
  try {
    const res = await groundApi('submitSurvey', {
      surveyId,
      respondent,
      answers,
      user_agent: navigator.userAgent || '',
    });
    if (!res || !res.ok) {
      if (btn) { btn.disabled = false; btn.innerHTML = '✓ Submit Answers'; btn.style.opacity = '1'; }
      showToast('Submit failed: ' + ((res && res.error) || 'unknown'));
      return;
    }
    card.innerHTML = ''
      + '<div style="text-align:center;padding:40px 20px">'
      +   '<div style="font-size:56px;margin-bottom:14px">✅</div>'
      +   '<div style="font-family:\'Barlow Condensed\',Arial,sans-serif;font-size:26px;font-weight:900;color:#1A5C1A !important;-webkit-text-fill-color:#1A5C1A !important;letter-spacing:.4px;margin-bottom:8px">THANKS, ' + esc(respondent.toUpperCase()) + '!</div>'
      +   '<div style="font-size:14px;color:#444 !important;-webkit-text-fill-color:#444 !important;line-height:1.5;margin-bottom:20px">Zac has been pinged. He + Claude will build the next slice based on your answers.</div>'
      +   '<button onclick="document.getElementById(\'sethSurveyOverlay\').remove()" style="padding:14px 24px;background:#7C3AED !important;color:#fff !important;-webkit-text-fill-color:#fff !important;border:none;border-radius:10px;font-size:14px;font-weight:900;cursor:pointer">Close</button>'
      + '</div>';
  } catch (e) {
    if (btn) { btn.disabled = false; btn.innerHTML = '✓ Submit Answers'; btn.style.opacity = '1'; }
    showToast('Network error: ' + e.message);
  }
}

// v10.598 — FedEx-direct rate preview modal. Triggered from the
// chip under the printer pill in Ground pack view. Read-only quote
// using the order's current boxes (from groundCurrentOrder.packages).
// Booking remains routed through ShipStation until v10.599 wires
// the actual ship endpoint.
async function openFedexRatePreview() {
  if (!groundCurrentOrder || !Array.isArray(groundCurrentOrder.packages) || !groundCurrentOrder.packages.length) {
    showToast('No boxes built yet — finish breakdown first');
    return;
  }
  const prior = document.getElementById('fedexRatePreviewOverlay');
  if (prior) prior.remove();
  const ov = document.createElement('div');
  ov.id = 'fedexRatePreviewOverlay';
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.82);z-index:10004;display:flex;align-items:center;justify-content:center;padding:18px;overflow-y:auto';
  const packages = groundCurrentOrder.packages.map(p => ({
    weightLb: Number(p.weight_lb || p.weight || 5),
    lengthIn: Number(p.length_in || p.length || 12),
    widthIn: Number(p.width_in || p.width || 9),
    heightIn: Number(p.height_in || p.height || 6),
  }));
  const pkgSummary = packages.map((p, i) =>
    `Box ${i+1}: ${p.lengthIn}×${p.widthIn}×${p.heightIn}" / ${p.weightLb}lb`
  ).join(' · ');
  ov.innerHTML = '<div class="no-dark keep-dark-text" onclick="event.stopPropagation()" style="background:#fff !important;color:#1a1a1a !important;-webkit-text-fill-color:#1a1a1a !important;border-radius:14px;padding:24px;max-width:560px;width:100%;max-height:88vh;overflow-y:auto">'
    + '<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin-bottom:6px">'
    +   '<div style="font-family:\'Barlow Condensed\',Arial,sans-serif;font-size:22px;font-weight:900;color:#5B21B6 !important;-webkit-text-fill-color:#5B21B6 !important;letter-spacing:.5px">⚡ FedEx Rate Preview</div>'
    +   '<button onclick="document.getElementById(\'fedexRatePreviewOverlay\').remove()" style="padding:8px 12px;background:#1a1a1a !important;color:#fff !important;-webkit-text-fill-color:#fff !important;border:none;border-radius:8px;font-size:13px;font-weight:700;cursor:pointer">✕</button>'
    + '</div>'
    + '<div style="font-size:13px;color:#444 !important;-webkit-text-fill-color:#444 !important;margin-bottom:10px">Order <strong>#' + esc(groundCurrentOrder.orderNumber) + '</strong> · ' + packages.length + ' box' + (packages.length === 1 ? '' : 'es') + '</div>'
    + '<div style="font-size:11px;color:#666 !important;-webkit-text-fill-color:#666 !important;background:#fafafa !important;padding:8px;border-radius:6px;margin-bottom:12px;font-family:\'JetBrains Mono\',monospace">' + esc(pkgSummary) + '</div>'
    + '<div style="display:flex;gap:8px;margin-bottom:12px">'
    +   '<label style="font-size:12px;color:#444 !important;-webkit-text-fill-color:#444 !important;font-weight:700;display:flex;align-items:center;gap:6px;cursor:pointer">'
    +     '<input type="checkbox" id="fxOneRateChk" style="cursor:pointer"> Include One Rate (XS/S/M/L/XL flat-rate boxes)'
    +   '</label>'
    + '</div>'
    + '<button id="fxGetRateBtn" style="width:100%;padding:12px 14px;background:#5B21B6 !important;color:#fff !important;-webkit-text-fill-color:#fff !important;border:none;border-radius:8px;font-size:14px;font-weight:900;cursor:pointer;letter-spacing:.4px;margin-bottom:14px">⚡ Get FedEx Rate</button>'
    + '<div id="fxRateBody" style="color:#1a1a1a !important;-webkit-text-fill-color:#1a1a1a !important"></div>'
    + '</div>';
  ov.onclick = (e) => { if (e.target === ov) ov.remove(); };
  document.body.appendChild(ov);
  document.getElementById('fxGetRateBtn').onclick = () => _runFedexRatePreview_(packages);
  // Auto-fire on open — the packer already tapped the chip.
  _runFedexRatePreview_(packages);
}

async function _runFedexRatePreview_(packages) {
  const body = document.getElementById('fxRateBody');
  const btn = document.getElementById('fxGetRateBtn');
  if (!body || !btn) return;
  const oneRate = document.getElementById('fxOneRateChk') && document.getElementById('fxOneRateChk').checked;
  btn.disabled = true;
  btn.textContent = '⟳ Quoting…';
  body.innerHTML = '<div style="text-align:center;padding:30px;color:#666 !important;-webkit-text-fill-color:#666 !important">⟳ Calling FedEx…</div>';
  try {
    const res = await groundApi('fedexParcelRateForOrder', {
      orderId: groundCurrentOrder.orderId,
      packages: packages,
      oneRate: !!oneRate,
    });
    btn.disabled = false;
    btn.textContent = oneRate ? '⚡ Re-quote (One Rate)' : '⚡ Re-quote';
    if (!res || !res.ok) {
      body.innerHTML = '<div style="background:#FAEAEA !important;color:#9E2222 !important;-webkit-text-fill-color:#9E2222 !important;border:1.5px solid #C43030;padding:12px;border-radius:8px;font-size:13px;font-weight:600">'
        + esc(String((res && res.error) || 'unknown error'))
        + '</div>';
      return;
    }
    const services = res.services || [];
    if (!services.length) {
      body.innerHTML = '<div style="padding:20px;text-align:center;color:#666 !important;-webkit-text-fill-color:#666 !important">No service options returned</div>';
      return;
    }
    const rows = services.map((s, i) => {
      const cheapest = i === 0;
      const price = s.totalNetCharge != null ? '$' + Number(s.totalNetCharge).toFixed(2) : '—';
      const list = (s.totalListCharge != null && s.totalListCharge !== s.totalNetCharge)
        ? '<span style="font-size:10px;color:#888 !important;-webkit-text-fill-color:#888 !important;text-decoration:line-through;margin-left:6px">$' + Number(s.totalListCharge).toFixed(2) + '</span>'
        : '';
      const transit = s.transitDays ? ' · ' + esc(String(s.transitDays).replace('_', ' ').toLowerCase()) : '';
      return '<div style="display:flex;align-items:center;gap:10px;padding:10px 12px;background:' + (cheapest ? 'rgba(0,200,83,.10)' : '#fafafa') + ' !important;border:1.5px solid ' + (cheapest ? '#00C853' : '#e0e0e0') + ' !important;border-radius:8px;margin-bottom:6px">'
        + '<div style="flex:1;min-width:0">'
        +   '<div style="font-weight:800;font-size:13px;color:#1a1a1a !important;-webkit-text-fill-color:#1a1a1a !important">' + esc(s.serviceName || s.serviceType) + '</div>'
        +   '<div style="font-size:11px;color:#666 !important;-webkit-text-fill-color:#666 !important;font-family:\'JetBrains Mono\',monospace">' + esc(s.serviceType) + transit + (s.deliveryDate ? ' · arr ' + esc(String(s.deliveryDate).slice(0,10)) : '') + '</div>'
        + '</div>'
        + '<div style="text-align:right">'
        +   '<div style="font-family:\'JetBrains Mono\',monospace;font-size:16px;font-weight:900;color:' + (cheapest ? '#1A5C1A' : '#1a1a1a') + ' !important;-webkit-text-fill-color:' + (cheapest ? '#1A5C1A' : '#1a1a1a') + ' !important">' + price + '</div>'
        +   list
        + '</div>'
        + (cheapest ? '<span style="font-size:10px;font-weight:900;color:#1A5C1A !important;-webkit-text-fill-color:#1A5C1A !important;letter-spacing:.5px">CHEAPEST</span>' : '')
        + '</div>';
    }).join('');
    body.innerHTML = '<div style="font-size:11px;color:#666 !important;-webkit-text-fill-color:#666 !important;font-weight:700;text-transform:uppercase;letter-spacing:.5px;margin-bottom:8px">' + services.length + ' service' + (services.length === 1 ? '' : 's') + ' returned — sorted cheapest first</div>'
      + rows
      + '<div style="margin-top:14px;padding:10px 12px;background:#FFF5E6 !important;border-left:4px solid #FF9100;color:#444 !important;-webkit-text-fill-color:#444 !important;border-radius:6px;font-size:12px;line-height:1.5">'
      +   '<strong>Read-only quote.</strong> Booking still routes through ShipStation. Direct FedEx booking lands in v10.599+.'
      + '</div>';
  } catch (e) {
    btn.disabled = false;
    btn.textContent = '⚡ Get FedEx Rate';
    body.innerHTML = '<div style="background:#FAEAEA !important;color:#9E2222 !important;-webkit-text-fill-color:#9E2222 !important;border:1.5px solid #C43030;padding:12px;border-radius:8px;font-size:13px;font-weight:600">'
      + esc('Network error: ' + (e.message || e))
      + '</div>';
  }
}

// v10.476 — Packer-override modal. Manager picks a box / carrier /
// service / weight / label for an unknown-SKU hold. Save scope picks
// between "just this order" (saves with max_qty=current qty, will
// satisfy this order only) and "save for up to N qty" (becomes a
// reusable rule via the packer_overrides rulebook tab).
// v10.637 (Indigo) — Persist packer-override boxes list in
// localStorage with a 1-hour TTL. The rulebook's box list rarely
// changes during a session, so re-fetching on every modal open
// (each costs ~600ms Apps Script round-trip) is wasted latency.
// On cold start, the in-memory cache rehydrates from localStorage
// if the entry is fresh enough; expired entries fall through to
// the network fetch and refresh both caches.
let _packerOverrideBoxesCache = null;
const PACKER_OVERRIDE_BOXES_LS_KEY = 'mbd_packer_override_boxes_v1';
const PACKER_OVERRIDE_BOXES_TTL_MS = 60 * 60 * 1000; // 1 hour
function _packerOverrideBoxesLsLoad_() {
  try {
    const raw = localStorage.getItem(PACKER_OVERRIDE_BOXES_LS_KEY);
    if (!raw) return null;
    const parsed = JSON.parse(raw);
    if (!parsed || !Array.isArray(parsed.boxes)) return null;
    if (Date.now() - Number(parsed.cached_at_ms || 0) > PACKER_OVERRIDE_BOXES_TTL_MS) return null;
    return parsed.boxes;
  } catch (e) { return null; }
}
function _packerOverrideBoxesLsSave_(boxes) {
  try {
    localStorage.setItem(PACKER_OVERRIDE_BOXES_LS_KEY, JSON.stringify({
      cached_at_ms: Date.now(),
      boxes: boxes || [],
    }));
  } catch (e) { /* localStorage full or denied — silent */ }
}

async function openPackerOverrideModal(sku, orderId, orderNumber) {
  const pin = (typeof promptManagerPin_ === 'function') ? promptManagerPin_('configure box for ' + sku) : null;
  if (!pin) return;
  const prior = document.getElementById('packerOverrideOverlay');
  if (prior) prior.remove();
  const ov = document.createElement('div');
  ov.id = 'packerOverrideOverlay';
  ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.82);z-index:10004;display:flex;align-items:center;justify-content:center;padding:18px;overflow-y:auto';
  ov.innerHTML = '<div class="no-dark keep-dark-text" onclick="event.stopPropagation()" style="background:#fff !important;color:#1a1a1a !important;-webkit-text-fill-color:#1a1a1a !important;border-radius:14px;padding:24px;max-width:560px;width:100%;max-height:88vh;overflow-y:auto">'
    + '<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:12px;margin-bottom:6px">'
    +   '<div style="font-family:\'Barlow Condensed\',Arial,sans-serif;font-size:22px;font-weight:900;color:#5B21B6 !important;-webkit-text-fill-color:#5B21B6 !important;letter-spacing:.5px">⚙ Configure Box</div>'
    +   '<button onclick="document.getElementById(\'packerOverrideOverlay\').remove()" style="padding:8px 12px;background:#1a1a1a !important;color:#fff !important;-webkit-text-fill-color:#fff !important;border:none;border-radius:8px;font-size:13px;font-weight:700;cursor:pointer">✕</button>'
    + '</div>'
    + '<div style="font-size:13px;color:#444 !important;-webkit-text-fill-color:#444 !important;margin-bottom:14px">Order <strong>#' + esc(orderNumber) + '</strong> · SKU <strong style="font-family:\'JetBrains Mono\',monospace;background:#FFF5E6 !important;padding:2px 8px;border-radius:4px;color:#5B21B6 !important;-webkit-text-fill-color:#5B21B6 !important">' + esc(sku) + '</strong></div>'
    + '<div id="packerOverrideBody" style="color:#1a1a1a !important;-webkit-text-fill-color:#1a1a1a !important"><div style="text-align:center;padding:30px;color:#666 !important">⟳ Loading boxes…</div></div>'
    + '</div>';
  ov.onclick = (e) => { if (e.target === ov) ov.remove(); };
  document.body.appendChild(ov);

  // v10.637 — hydrate from localStorage if available + fresh.
  if (!_packerOverrideBoxesCache) {
    _packerOverrideBoxesCache = _packerOverrideBoxesLsLoad_();
  }
  // Fetch only if still empty (no fresh LS entry).
  if (!_packerOverrideBoxesCache) {
    try {
      const r = await groundApi('listBoxesForOverride', {});
      if (r && r.ok) {
        _packerOverrideBoxesCache = r.boxes || [];
        _packerOverrideBoxesLsSave_(_packerOverrideBoxesCache);
      }
    } catch (e) {
      document.getElementById('packerOverrideBody').innerHTML = '<div style="color:#c62828 !important;-webkit-text-fill-color:#c62828 !important;padding:20px">Failed to load boxes: ' + esc(String(e.message || e)) + '</div>';
      return;
    }
  }
  _renderPackerOverrideForm(sku, orderId, orderNumber, pin);
}

function _renderPackerOverrideForm(sku, orderId, orderNumber, pin) {
  const body = document.getElementById('packerOverrideBody');
  if (!body) return;
  const boxes = _packerOverrideBoxesCache || [];
  // v10.599 — CUSTOM option first (Zac 2026-06-16). Reveals inline
  // length/width/height inputs; saving auto-creates a CUSTOM-<L>x<W>x<H>
  // boxes-tab row via the server.
  // v10.734 — mode-aware box list. The "FedEx One Rate" checkbox
  // calls _packerOverrideRebuildBoxes_() which re-renders the box
  // select using only FEDEX-ONE-RATE-* boxes. Default mode shows
  // everything EXCEPT the One Rate boxes (they only appear in
  // One Rate mode — the carrier+service requirements differ).
  window._packerOverrideBoxesAll = boxes;
  window._packerOverrideMode = 'standard';
  const boxOptions = _packerOverrideBuildBoxOptions_('standard', boxes);
  const inputStyle = 'width:100%;padding:10px 12px;background:#fff !important;color:#1a1a1a !important;-webkit-text-fill-color:#1a1a1a !important;border:1.5px solid #ccc;border-radius:8px;font-size:14px;font-family:inherit;box-sizing:border-box';
  const labelStyle = 'display:block;font-size:11px;font-weight:800;text-transform:uppercase;letter-spacing:.5px;color:#5B21B6 !important;-webkit-text-fill-color:#5B21B6 !important;margin-bottom:4px;margin-top:14px';
  const smallInputStyle = 'flex:1;padding:10px 12px;background:#fff !important;color:#1a1a1a !important;-webkit-text-fill-color:#1a1a1a !important;border:1.5px solid #ccc;border-radius:8px;font-size:14px;font-family:inherit;box-sizing:border-box;min-width:0';
  body.innerHTML =
      '<div style="display:flex;justify-content:space-between;align-items:baseline;margin-top:14px;margin-bottom:4px">'
    +   '<label style="' + labelStyle + ';margin-top:0;margin-bottom:0">Box</label>'
    +   '<label style="font-size:11px;font-weight:700;color:#5B21B6 !important;-webkit-text-fill-color:#5B21B6 !important;display:flex;align-items:center;gap:6px;cursor:pointer;letter-spacing:.3px">'
    +     '<input type="checkbox" id="poOneRateToggle" onchange="_packerOverrideOneRateToggle_(this.checked)" style="margin:0;width:14px;height:14px"> 📦 FedEx One Rate'
    +   '</label>'
    + '</div>'
    + '<select id="poBoxSku" style="' + inputStyle + '" onchange="_packerOverrideBoxChanged()">' + boxOptions + '</select>'
    + '<div id="poDims" style="font-size:11px;color:#666 !important;-webkit-text-fill-color:#666 !important;margin-top:4px"></div>'
    // v10.599 — inline dim inputs, hidden until CUSTOM selected.
    + '<div id="poCustomDims" style="display:none;margin-top:8px">'
    +   '<div style="font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.5px;color:#7C3AED !important;-webkit-text-fill-color:#7C3AED !important;margin-bottom:6px">Custom box — inches</div>'
    +   '<div style="display:flex;gap:8px;align-items:center">'
    +     '<input type="number" id="poCustomLen" step="0.25" min="0.5" placeholder="L" style="' + smallInputStyle + '">'
    +     '<span style="color:#888 !important;-webkit-text-fill-color:#888 !important;font-weight:700">×</span>'
    +     '<input type="number" id="poCustomWid" step="0.25" min="0.5" placeholder="W" style="' + smallInputStyle + '">'
    +     '<span style="color:#888 !important;-webkit-text-fill-color:#888 !important;font-weight:700">×</span>'
    +     '<input type="number" id="poCustomHgt" step="0.25" min="0.5" placeholder="H" style="' + smallInputStyle + '">'
    +   '</div>'
    +   '<div style="font-size:10px;color:#666 !important;-webkit-text-fill-color:#666 !important;margin-top:4px;font-style:italic">Saved as <code>CUSTOM-LxWxH</code> in the boxes tab — reusable on future overrides.</div>'
    + '</div>'
    + '<label style="' + labelStyle + '">Carrier</label>'
    + '<select id="poCarrier" style="' + inputStyle + '" onchange="_packerOverrideCarrierChanged()">'
    +   '<option value="">— pick a carrier —</option>'
    +   '<option value="usps">USPS</option>'
    +   '<option value="fedex">FedEx</option>'
    +   '<option value="ups">UPS</option>'
    + '</select>'
    + '<label style="' + labelStyle + '">Service</label>'
    + '<select id="poService" style="' + inputStyle + '">'
    +   '<option value="">— pick a carrier first —</option>'
    + '</select>'
    + '<label style="' + labelStyle + '">Weight override (lb, optional)</label>'
    + '<input type="number" id="poWeight" step="0.05" placeholder="leave blank to use box default" style="' + inputStyle + '">'
    + '<label style="' + labelStyle + '">Label text (use {qty} for the quantity)</label>'
    + '<input type="text" id="poLabel" placeholder="e.g. {qty}x OVERLAY HINGE" style="' + inputStyle + '">'
    + '<label style="' + labelStyle + '">Save scope</label>'
    + '<div style="display:flex;gap:8px;align-items:center;margin-top:4px">'
    +   '<label style="font-size:13px;color:#444 !important;-webkit-text-fill-color:#444 !important;font-weight:600;display:flex;align-items:center;gap:4px"><input type="radio" name="poScope" value="oneshot" checked> Just this order</label>'
    +   '<label style="font-size:13px;color:#444 !important;-webkit-text-fill-color:#444 !important;font-weight:600;display:flex;align-items:center;gap:4px"><input type="radio" name="poScope" value="save"> Save for up to</label>'
    +   '<input type="number" id="poMaxQty" min="1" max="999" value="8" style="width:70px;padding:6px 10px;background:#fff !important;color:#1a1a1a !important;-webkit-text-fill-color:#1a1a1a !important;border:1.5px solid #ccc;border-radius:6px;font-size:13px">'
    +   '<span style="font-size:13px;color:#444 !important;-webkit-text-fill-color:#444 !important">qty</span>'
    + '</div>'
    + '<div style="display:flex;gap:8px;margin-top:18px">'
    // v10.600 — added po-save-btn class so _guardedAction_'s in-flight
    // indicator selector can find this button. Zac 2026-06-16: "no
    // immediate indication it was working" — was because the selector
    // never matched, so the busyText/disable never applied.
    +   '<button class="po-save-btn" onclick="_savePackerOverride(\'' + esc(sku) + '\',\'' + esc(orderId) + '\',\'' + esc(orderNumber) + '\',\'' + esc(pin) + '\')" style="flex:1;padding:14px 18px;background:#00C853 !important;color:#fff !important;-webkit-text-fill-color:#fff !important;border:none;border-radius:8px;font-size:14px;font-weight:900;cursor:pointer;letter-spacing:.4px">✓ Save & Resume</button>'
    +   '<button onclick="document.getElementById(\'packerOverrideOverlay\').remove()" style="padding:14px 18px;background:#1a1a1a !important;color:#fff !important;-webkit-text-fill-color:#fff !important;border:none;border-radius:8px;font-size:14px;font-weight:700;cursor:pointer">Cancel</button>'
    + '</div>';
}

function _packerOverrideBoxChanged() {
  const sel = document.getElementById('poBoxSku');
  const opt = sel.options[sel.selectedIndex];
  const dims = document.getElementById('poDims');
  const customWrap = document.getElementById('poCustomDims');
  const car = document.getElementById('poCarrier');
  const svc = document.getElementById('poService');
  // v10.599 — CUSTOM mode: reveal inline dim inputs, hide the dims
  // summary line (it's empty until they type).
  if (opt && opt.value === 'CUSTOM') {
    if (dims) dims.textContent = '';
    if (customWrap) customWrap.style.display = '';
    return;
  }
  if (customWrap) customWrap.style.display = 'none';
  if (!opt || !opt.value) { if (dims) dims.textContent = ''; return; }
  dims.textContent = opt.dataset.len + '×' + opt.dataset.wid + '×' + opt.dataset.hgt + '" · ' + opt.dataset.wt + ' lb';
  if (opt.dataset.car && !car.value) { car.value = opt.dataset.car; _packerOverrideCarrierChanged(); }
  if (opt.dataset.svc) { setTimeout(() => { if (svc) svc.value = opt.dataset.svc; }, 20); }
}

function _packerOverrideCarrierChanged() {
  const car = document.getElementById('poCarrier').value;
  const svc = document.getElementById('poService');
  // v10.734 — services depend on mode. Standard mode = regular
  // carrier services. One Rate mode = only fedex_one_rate_* services
  // (carrier locked to fedex).
  const SERVICES = {
    usps: ['usps_ground_advantage', 'usps_priority_mail', 'usps_priority_mail_express', 'usps_media_mail', 'usps_parcel_select_ground'],
    fedex: ['fedex_home_delivery', 'fedex_ground', 'fedex_2day', 'fedex_express_saver', 'fedex_standard_overnight'],
    ups: ['ups_ground', 'ups_3_day_select', 'ups_2nd_day_air', 'ups_next_day_air_saver', 'ups_next_day_air'],
  };
  // v10.949 — Zac 2026-07-02: FedEx One Rate offers 5 delivery
  // speeds, not one hardcoded service. ShipEngine V2 rejects
  // fedex_one_rate_* (those are the box names, not services).
  // The valid One Rate services are just the standard FedEx delivery
  // codes — ShipEngine applies One Rate pricing based on the
  // service + package_code combination.
  const ONE_RATE = [
    ['fedex_2day', 'FedEx 2Day (One Rate — default, 2 business days)'],
    ['fedex_2day_am', 'FedEx 2Day AM (One Rate — 2 days, morning)'],
    ['fedex_express_saver', 'FedEx Express Saver (One Rate — 3 business days)'],
    ['fedex_standard_overnight', 'FedEx Standard Overnight (One Rate — next PM)'],
    ['fedex_priority_overnight', 'FedEx Priority Overnight (One Rate — next AM)'],
    ['fedex_first_overnight', 'FedEx First Overnight (One Rate — next early AM)'],
  ];
  const mode = window._packerOverrideMode || 'standard';
  const isOneRate = (mode === 'one_rate' && car === 'fedex');
  if (isOneRate) {
    svc.innerHTML = '<option value="">— pick a One Rate service —</option>'
      + ONE_RATE.map(pair => '<option value="' + pair[0] + '">' + pair[1] + '</option>').join('');
  } else {
    const opts = SERVICES[car] || [];
    svc.innerHTML = opts.length
      ? '<option value="">— pick a service —</option>' + opts.map(s => '<option value="' + s + '">' + s + '</option>').join('')
      : '<option value="">— pick a carrier first —</option>';
  }
}

// v10.734 — build the box-select options for the current mode.
//   standard: all rulebook boxes + CUSTOM, EXCLUDES the One Rate ones
//             (they only appear in one_rate mode).
//   one_rate: ONLY the FEDEX-ONE-RATE-* boxes. No CUSTOM (One Rate has
//             fixed sizes — custom dims aren't a thing for it).
function _packerOverrideBuildBoxOptions_(mode, boxes) {
  const list = boxes || window._packerOverrideBoxesAll || [];
  if (mode === 'one_rate') {
    const oneRate = list.filter(b => /^FEDEX-ONE-RATE-/.test(b.box_sku));
    if (!oneRate.length) return '<option value="">(no One Rate boxes — run seedFedexOneRateBoxes)</option>';
    return '<option value="">— pick a One Rate box —</option>'
      + oneRate.map(b => '<option value="' + esc(b.box_sku) + '" data-len="' + b.length_in + '" data-wid="' + b.width_in + '" data-hgt="' + b.height_in + '" data-wt="' + b.weight_lb + '" data-svc="' + esc(b.service_hint) + '" data-car="' + esc(b.carrier_hint) + '">'
        + esc(b.box_sku) + ' · ' + b.length_in + '×' + b.width_in + '×' + b.height_in + '"</option>').join('');
  }
  const standard = list.filter(b => !/^FEDEX-ONE-RATE-/.test(b.box_sku));
  return '<option value="">— pick a box —</option>'
    + '<option value="CUSTOM">✎ Custom size (enter dimensions)</option>'
    + standard.map(b => '<option value="' + esc(b.box_sku) + '" data-len="' + b.length_in + '" data-wid="' + b.width_in + '" data-hgt="' + b.height_in + '" data-wt="' + b.weight_lb + '" data-svc="' + esc(b.service_hint) + '" data-car="' + esc(b.carrier_hint) + '">'
        + esc(b.box_sku) + ' · ' + b.length_in + '×' + b.width_in + '×' + b.height_in + '" / ' + b.weight_lb + 'lb' + (b.carrier_hint ? ' / ' + esc(b.carrier_hint) : '') + '</option>').join('');
}

// v10.734 — toggle One Rate mode. Re-renders the box dropdown, locks
// carrier to fedex (or unlocks it), and re-runs the carrier-changed
// handler so the service dropdown matches.
function _packerOverrideOneRateToggle_(checked) {
  window._packerOverrideMode = checked ? 'one_rate' : 'standard';
  const boxSel = document.getElementById('poBoxSku');
  const carSel = document.getElementById('poCarrier');
  const dims = document.getElementById('poDims');
  const customWrap = document.getElementById('poCustomDims');
  if (boxSel) boxSel.innerHTML = _packerOverrideBuildBoxOptions_(window._packerOverrideMode);
  if (dims) dims.textContent = '';
  if (customWrap) customWrap.style.display = 'none';
  if (carSel) {
    if (checked) {
      carSel.value = 'fedex';
      carSel.disabled = true;
      carSel.style.opacity = '0.6';
      carSel.style.cursor = 'not-allowed';
    } else {
      carSel.disabled = false;
      carSel.style.opacity = '';
      carSel.style.cursor = '';
    }
  }
  _packerOverrideCarrierChanged();
}

async function _savePackerOverride(sku, orderId, orderNumber, pin) {
  const boxSku = document.getElementById('poBoxSku').value;
  const carrier = document.getElementById('poCarrier').value;
  const service = document.getElementById('poService').value;
  const weight = Number(document.getElementById('poWeight').value) || 0;
  const labelText = document.getElementById('poLabel').value.trim();
  const scope = document.querySelector('input[name="poScope"]:checked').value;
  const maxQty = scope === 'oneshot' ? 1 : Math.max(1, Number(document.getElementById('poMaxQty').value) || 1);
  if (!boxSku) { showToast('Pick a box first'); return; }
  // v10.599 — custom-box dim validation client-side.
  let customLen = 0, customWid = 0, customHgt = 0;
  if (boxSku === 'CUSTOM') {
    customLen = Number((document.getElementById('poCustomLen') || {}).value) || 0;
    customWid = Number((document.getElementById('poCustomWid') || {}).value) || 0;
    customHgt = Number((document.getElementById('poCustomHgt') || {}).value) || 0;
    if (!(customLen > 0 && customWid > 0 && customHgt > 0)) {
      showToast('Custom box needs L × W × H (in inches)');
      return;
    }
  }
  if (!carrier) { showToast('Pick a carrier'); return; }
  if (!service) { showToast('Pick a service'); return; }
  let confirmedBy = '';
  try { confirmedBy = (localStorage.getItem('mbd_ground_packer') || localStorage.getItem('mbd_device_name') || '').trim(); } catch (e) {}
  // v10.513 — fires TWO chained calls (savePackerOverride + resumeOrderFromHold).
  // Double-tap = 4 parallel requests + duplicate override rows.
  return _guardedAction_({
    key: 'savePackerOverride:' + (orderNumber || sku),
    btnSelector: '#packerOverrideOverlay button.po-save-btn',
    busyText: '⏳ Saving…',
    action: async () => {
      try {
        const res = await groundApi('savePackerOverride', {
          sku: sku, max_qty: maxQty, box_sku: boxSku, weight_lb: weight,
          carrier: carrier, service: service, label_text: labelText,
          manager_pin: pin, created_by: confirmedBy,
          // v10.599 — custom box dims (only sent when boxSku==='CUSTOM').
          length_in: customLen || undefined,
          width_in: customWid || undefined,
          height_in: customHgt || undefined,
        });
        if (_handleApiErrorWithPin_(res, 'Save failed')) return;
        try {
          const rr = await groundApi('resumeOrderFromHold', { orderId: Number(orderId) });
          if (rr && rr.ok) showToast('✓ Override saved + #' + orderNumber + ' resumed (' + (scope === 'oneshot' ? 'one-shot' : 'up to ' + maxQty + 'x') + ')');
          else showToast('Override saved · resume failed: ' + ((rr && rr.error) || 'unknown'));
        } catch (rrErr) {
          showToast('Override saved · resume error: ' + rrErr.message);
        }
        const ov = document.getElementById('packerOverrideOverlay');
        if (ov) ov.remove();
        // v10.600 — Zac 2026-06-16: post-save landed on Holds view
        // instead of Ground with the resumed order. Switch to Ground +
        // refresh queue so the just-resumed order appears at the top
        // and the packer can tap it without backtracking.
        // Also close the Holds panel if it's open (the modal was
        // launched from it).
        try { document.getElementById('holdsOverlay') && document.getElementById('holdsOverlay').remove(); } catch (_e) {}
        if (typeof switchTab === 'function') {
          switchTab('ground');
        }
        if (typeof refreshGroundQueue === 'function') {
          // Brief delay so resumeOrderFromHold's write to OrderPack
          // settles before the queue re-fetch (avoids re-rendering
          // the order as still-held).
          setTimeout(() => refreshGroundQueue(), 250);
        }
      } catch (err) {
        showToast('Save error: ' + err.message);
      }
    },
  });
}

// v10.490 — Beacon-release handler. Manager confirms the Beacon-Hold
// is OK to pack; Bedrock stores an override that bypasses the cf1
// substring filter on the Ground queue. No ShipStation API calls.
async function beaconReleaseFromPanel_(orderId, orderNumber) {
  const ok = confirm(
    'Bedrock-release Beacon-Hold for #' + orderNumber + '?\n\n'
    + 'Use this AFTER CS has reviewed + cleared the Beacon flag in your normal CS workflow.\n\n'
    + 'Bedrock will add this order to a release-override list so the Ground queue stops blocking it,\n'
    + 'WITHOUT requiring you to clear Custom Field 1 in ShipStation (Beacon leaves "Beacon-Hold" in CF1 even after release).\n\n'
    + 'Continue?'
  );
  if (!ok) return;
  const pin = (typeof promptManagerPin_ === 'function') ? promptManagerPin_('Bedrock-release #' + orderNumber) : null;
  if (!pin) return;
  let releasedBy = '';
  try { releasedBy = (localStorage.getItem('mbd_ground_packer') || localStorage.getItem('mbd_device_name') || '').trim(); } catch (e) {}
  return _guardedAction_({
    key: 'beaconRelease:' + orderNumber,
    btnSelector: null,
    busyText: '',
    action: async () => {
      try {
        const res = await groundApi('markBeaconReleased', {
          orderId: orderId,
          orderNumber: orderNumber,
          releasedBy: releasedBy,
          manager_pin: pin,
        });
        if (!res || !res.ok) {
          if (res && /pin/i.test(String(res.error || '')) && typeof clearManagerPin_ === 'function') clearManagerPin_();
          showToast('Release failed: ' + ((res && res.error) || 'unknown'));
          return;
        }
        showToast(res.already_released ? '✓ #' + orderNumber + ' was already Bedrock-released' : '✓ #' + orderNumber + ' Bedrock-released');
        if (typeof openHoldsPanel === 'function') openHoldsPanel();
      } catch (err) {
        showToast('Release error: ' + err.message);
      }
    },
  });
}

async function confirmSizeAndResumeFromPanel_(orderId, orderNumber) {
  const ok = confirm(
    'Confirm size for #' + orderNumber + '?\n\n'
    + 'Use this AFTER you\'ve verified with the customer that the order '
    + 'is correctly Single (or Twin / SingleXL — whichever matches what '
    + 'they actually want).\n\n'
    + 'This clears the hold AND marks the order so it won\'t re-hold on '
    + 'the next pack attempt.'
  );
  if (!ok) return;
  let confirmedBy = '';
  try { confirmedBy = (localStorage.getItem('mbd_ground_packer') || localStorage.getItem('mbd_device_name') || '').trim(); } catch (e) {}
  return _guardedAction_({
    key: 'confirmSize:' + orderNumber,
    btnSelector: null,
    busyText: '',
    action: async () => {
      try {
        const res = await groundApi('confirmSizeAndResume', {
          orderId: Number(orderId),
          confirmedBy: confirmedBy,
        });
        if (!res || !res.ok) {
          showToast('Confirm failed: ' + ((res && res.error) || 'unknown'));
          return;
        }
        showToast('✓ #' + orderNumber + ' size confirmed + resumed');
        openHoldsPanel();
      } catch (err) {
        showToast('Confirm error: ' + err.message);
      }
    },
  });
}

// v10.223 — permanent-delete a hold record. Per Zac 2026-05-22 20:00
// EDT: "you have the old orders that got stuck from ShipStation in
// 'holds' as though they're anything legitimate, with no way to
// permanently delete/clear them". Manager-PIN gated so a stray tap
// doesn't lose data.
async function deleteHoldFromPanel_(orderId, orderNumber, holdKind) {
  if (!confirm('Permanently DELETE the hold record for #' + orderNumber + '?\n\nThis removes the row from the underlying tab. The order itself in ShipStation/PackingQueue is NOT touched. Use this when a hold is stale + you want it out of the list.')) return;
  const pin = prompt('Manager PIN (delete is irreversible):');
  if (!pin) return;
  // v10.512 — irreversible delete; multi-tap could race-delete sibling
  // holds if the panel re-renders mid-call. Guard hard.
  return _guardedAction_({
    key: 'deleteHold:' + orderNumber + ':' + (holdKind || ''),
    btnSelector: null,
    busyText: '',
    action: async () => {
      try {
        const res = await groundApi('deleteHold', {
          orderId: Number(orderId) || 0,
          orderNumber: String(orderNumber),
          holdKind: String(holdKind || ''),
          managerPin: pin,
        });
        if (!res || !res.ok) { showToast('Delete failed: ' + ((res && res.error) || 'unknown')); return; }
        showToast('🗑 #' + orderNumber + ' removed from holds');
        openHoldsPanel();
      } catch (err) {
        showToast('Delete error: ' + err.message);
      }
    },
  });
}

